window.STUDY_DATA = {"version": 1, "course": "ACT6121", "updated": "2026-10-21", "chapters": [{"id": "l1", "title": {"en": "Cost foundations", "zh": "成本基础"}, "subtitle": "先明确成本对象，再判断分类。", "sections": ["1-1 管理会计概览", "1-2 基本成本概念", "1-3 人工成本的特殊处理"], "cards": [{"id": "l1-purpose", "section": 0, "title": {"en": "Managerial vs financial accounting", "zh": "管理会计与财务会计"}, "pages": "8–10, 18–24", "body": ["管理会计服务内部经理，提供财务与非财务信息，强调相关性、及时性和面向未来的决策；可以细分到产品、客户或部门。财务会计主要服务外部使用者，强调历史、可验证性、精确性和整体报告。", "规划 Planning 设定目标与预算；控制 Controlling 比较实际与计划并纠偏；决策 Decision making 在方案间选择。三者相互关联，不是只有决策才需要会计信息。", "历史脉络：早期产品成本计量，铁路与钢铁成本控制，随后扩展到规划和绩效管理。内部报告形式按管理需求设计。"], "summary": "Managerial accounting supports planning, control and decisions with relevant, timely financial and nonfinancial information.", "formula": "Plan → Act → Compare → Adjust", "trap": "编预算是规划；分析实际偏差是控制。", "example": {"type": "choice", "prompt": {"en": "A manager compares actual costs with budget. Which function?", "zh": "经理将实际成本与预算比较，属于哪项职能？"}, "options": [{"en": "Control", "zh": "控制"}, {"en": "Planning only", "zh": "仅规划"}, {"en": "External reporting", "zh": "外部报告"}], "answer": 0, "solution": {"en": "Comparison provides feedback for control.", "zh": "实际与预算的比较提供控制反馈。"}}, "concept": {"type": "choice", "prompt": {"en": "Who is the primary user of managerial accounting?", "zh": "管理会计的主要使用者是谁？"}, "options": [{"en": "Internal managers", "zh": "内部经理"}, {"en": "External shareholders only", "zh": "仅外部股东"}, {"en": "Tax authorities only", "zh": "仅税务机关"}], "answer": 0, "solution": {"en": "Reports are tailored to internal decisions.", "zh": "报告为内部管理决策定制。"}}, "applications": [{"type": "choice", "prompt": {"en": "Choosing between two suppliers is primarily:", "zh": "在两个供应商中选择主要属于："}, "options": [{"en": "Decision making", "zh": "决策"}, {"en": "Historical disclosure", "zh": "历史披露"}, {"en": "Inventory counting", "zh": "盘点"}], "answer": 0, "solution": {"en": "The manager selects an alternative.", "zh": "决策就是选择备选方案。"}}, {"type": "choice", "prompt": {"en": "Preparing next year’s sales budget is:", "zh": "编制明年销售预算属于："}, "options": [{"en": "Control", "zh": "控制"}, {"en": "Planning", "zh": "规划"}, {"en": "Audit", "zh": "审计"}], "answer": 1, "solution": {"en": "A budget specifies how future goals will be achieved.", "zh": "预算说明未来目标如何实现。"}}]}, {"id": "l1-ai", "section": 0, "title": {"en": "Value creation and human judgment", "zh": "价值创造与 AI 下的管理判断"}, "pages": "11–17, 25", "body": ["管理会计不仅记录数字，也识别增值与非增值活动，帮助效率、战略、跨职能协作及转型。非增值活动如返工可能暂时必要，但应分析其成因。", "AI 可自动化发票、对账、风险识别和预测；财务人员要解释输出并结合业务。信息集中或分散，应取决于谁需要什么信息来做什么决策。", "成本模型的假设、成本对象、因果关系和最终决策仍由人判断。课件里的公司新闻属于课堂情境，本复习不将其当作经独立验证的时事结论。"], "summary": "AI can improve measurement and prediction; managers remain responsible for assumptions, relevance and decisions.", "formula": "Data + assumptions → Model → Interpretation → Decision", "trap": "相关性不等于因果关系；数据更快不保证模型正确。", "example": {"type": "choice", "prompt": {"en": "AI predicts a lower defect rate. Who chooses whether to invest?", "zh": "AI 预测缺陷率下降，由谁决定是否投资？"}, "options": [{"en": "Management using evidence", "zh": "管理者依据证据判断"}, {"en": "The model automatically", "zh": "模型自动决定"}, {"en": "The invoice system", "zh": "发票系统"}], "answer": 0, "solution": {"en": "Prediction informs judgment but does not replace it.", "zh": "预测支持判断，不能代替判断。"}}, "concept": {"type": "choice", "prompt": {"en": "Which is usually a non-value-added activity?", "zh": "哪项通常是非增值活动？"}, "options": [{"en": "Rework caused by errors", "zh": "错误造成的返工"}, {"en": "Required product assembly", "zh": "必要的产品装配"}, {"en": "Designing requested features", "zh": "设计客户所需功能"}], "answer": 0, "solution": {"en": "Rework consumes resources without adding desired functionality.", "zh": "返工消耗资源而没有增加客户所需功能。"}}, "applications": [{"type": "choice", "prompt": {"en": "More detailed data eliminate the need to choose a cost object.", "zh": "更细数据会消除选择成本对象的必要性。"}, "options": [{"en": "True", "zh": "正确"}, {"en": "False", "zh": "错误"}], "answer": 1, "solution": {"en": "The cost object depends on the managerial question.", "zh": "成本对象取决于管理问题。"}}, {"type": "choice", "prompt": {"en": "Decentralized information should be designed around:", "zh": "分散化信息系统应围绕："}, "options": [{"en": "Decision needs", "zh": "决策需要"}, {"en": "The largest possible report", "zh": "尽可能大的报告"}, {"en": "Past spending only", "zh": "仅历史支出"}], "answer": 0, "solution": {"en": "Relevant information must reach the responsible decision maker.", "zh": "相关信息应到达负责决策的人。"}}]}, {"id": "l1-object", "section": 1, "title": {"en": "Cost objects, direct and indirect costs", "zh": "成本对象、直接与间接成本"}, "pages": "29–31", "body": ["成本对象是希望计量成本的任何事物，如产品、服务、部门、客户。直接成本能方便、经济地追溯到该对象；间接成本需要分配。共同成本同时支持多个对象。", "同一成本的分类会随对象改变：工厂经理薪酬对整个工厂可直接追溯，但对单件产品通常间接。分类前必须写清“相对于谁”。", "直接/间接与固定/变动是不同维度；固定薪酬也可以是某部门的直接成本。"], "summary": "Directness is relative to the cost object, not to cost behavior.", "formula": "Cost object first → Trace if feasible → Allocate otherwise", "trap": "不要把 direct 当作 variable 的同义词。", "example": {"type": "choice", "prompt": {"en": "A factory manager’s salary is indirect to individual products but direct to the factory. Correct?", "zh": "厂长工资对单件产品间接，对工厂直接，正确吗？"}, "options": [{"en": "Yes", "zh": "是"}, {"en": "No", "zh": "否"}], "answer": 0, "solution": {"en": "Changing the cost object changes traceability.", "zh": "成本对象改变，可追溯性随之改变。"}}, "concept": {"type": "choice", "prompt": {"en": "What must be specified before classifying a cost as direct?", "zh": "判断直接成本前应先明确什么？"}, "options": [{"en": "Cost object", "zh": "成本对象"}, {"en": "Profit", "zh": "利润"}, {"en": "Selling price", "zh": "售价"}], "answer": 0, "solution": {"en": "Traceability is evaluated relative to an object.", "zh": "可追溯性总是相对于成本对象。"}}, "applications": [{"type": "choice", "prompt": {"en": "CEO salary supporting three divisions is normally:", "zh": "支持三个事业部的 CEO 工资通常是："}, "options": [{"en": "Common indirect cost to divisions", "zh": "事业部的共同间接成本"}, {"en": "Direct materials", "zh": "直接材料"}, {"en": "Variable cost per unit", "zh": "单位变动成本"}], "answer": 0, "solution": {"en": "It supports multiple divisions and cannot be traced to one.", "zh": "同时支持多个事业部，不能归属于某一个。"}}, {"type": "choice", "prompt": {"en": "A dedicated product designer’s fixed salary can be direct to a product line.", "zh": "专门产品设计师的固定薪酬可以是产品线直接成本。"}, "options": [{"en": "True", "zh": "正确"}, {"en": "False", "zh": "错误"}], "answer": 0, "solution": {"en": "Direct and fixed describe separate dimensions.", "zh": "直接和固定属于不同分类维度。"}}]}, {"id": "l1-mfg", "section": 1, "title": {"en": "Manufacturing, prime and conversion costs", "zh": "制造成本、主要成本与加工成本"}, "pages": "32–40", "body": ["制造成本分为直接材料 DM、直接人工 DL、制造费用 MOH。润滑油等难以经济追溯的材料、维修工工资、厂房租金属于 MOH。销售和行政属于非制造成本。", "主要成本 Prime cost = DM + DL；加工成本 Conversion cost = DL + MOH。两者都含 DL，不能直接相加当总制造成本。", "分类看用途：工厂设备折旧是 MOH；行政办公设备折旧是行政费用；发货运费通常是销售费用。"], "summary": "Manufacturing cost is DM + DL + MOH. Prime and conversion costs overlap in direct labor.", "formula": "Prime = DM + DL; Conversion = DL + MOH", "trap": "工厂经理对工厂可直接追溯，但对产品通常是间接人工，归入 MOH。", "example": {"type": "number", "prompt": {"en": "DM $90, DL $60, MOH $40. Find conversion cost.", "zh": "DM 90、DL 60、MOH 40，计算加工成本。"}, "answer": 100, "solution": {"en": "Conversion = 60 + 40 = 100.", "zh": "加工成本 = 60 + 40 = 100。"}, "unit": "$", "tolerance": 0.01}, "concept": {"type": "choice", "prompt": {"en": "Factory equipment depreciation is:", "zh": "工厂设备折旧属于："}, "options": [{"en": "Manufacturing overhead", "zh": "制造费用"}, {"en": "Direct materials", "zh": "直接材料"}, {"en": "Selling expense", "zh": "销售费用"}], "answer": 0, "solution": {"en": "It supports manufacturing but is not directly traced to units.", "zh": "支持制造，但通常不直接追溯到单件产品。"}}, "applications": [{"type": "number", "prompt": {"en": "DM $120, DL $80, MOH $50. Find prime cost.", "zh": "DM 120、DL 80、MOH 50，计算主要成本。"}, "answer": 200, "solution": {"en": "Prime = 120 + 80 = 200.", "zh": "主要成本 = 120 + 80 = 200。"}, "unit": "$", "tolerance": 0.01}, {"type": "number", "prompt": {"en": "Prime cost is $240 and DL is $90. MOH is $70. Find total manufacturing cost.", "zh": "主要成本 240、DL 90、MOH 70，计算总制造成本。"}, "answer": 310, "solution": {"en": "DM = 240 − 90 = 150; total = 150 + 90 + 70 = 310.", "zh": "DM = 240 − 90 = 150；总额 = 150 + 90 + 70 = 310。"}, "unit": "$", "tolerance": 0.01}]}, {"id": "l1-flow", "section": 1, "title": {"en": "Product costs, period costs and inventory flow", "zh": "产品成本、期间成本与存货流转"}, "pages": "41–54", "body": ["本节按吸收成本法：制造成本先进入存货，售出时才成为 COGS；销售和行政费用当期计入损益。Product cost 并不是发生时就全部费用化。", "制造企业有原材料 RM、在产品 WIP、产成品 FG。RM 领用进入生产，DM、DL、MOH 进入 WIP，完工转入 FG，售出转为 COGS。商业企业主要有商品存货。", "任何存货账户均满足期初 + 增加 − 减少 = 期末。计算 DM used 时若包含间接材料，要先减去间接材料；不要把购买金额直接当本期耗用。"], "summary": "Inventoriable costs flow through RM, WIP and FG before becoming COGS when sold.", "formula": "COGM = Beginning WIP + manufacturing costs added − Ending WIP; COGS = Beginning FG + COGM − Ending FG", "trap": "现金付款时点不决定产品成本何时计入损益。", "example": {"type": "number", "prompt": {"en": "Beginning FG $20, COGM $150, ending FG $30. Find unadjusted COGS.", "zh": "期初 FG 20、COGM 150、期末 FG 30，求未调整 COGS。"}, "answer": 140, "solution": {"en": "20 + 150 − 30 = 140.", "zh": "20 + 150 − 30 = 140。"}, "unit": "$", "tolerance": 0.01}, "concept": {"type": "choice", "prompt": {"en": "Unsold finished goods are normally reported as:", "zh": "未售出的产成品通常列为："}, "options": [{"en": "Inventory asset", "zh": "存货资产"}, {"en": "Selling expense", "zh": "销售费用"}, {"en": "Revenue", "zh": "收入"}], "answer": 0, "solution": {"en": "Their product cost remains on the balance sheet.", "zh": "产品成本仍留在资产负债表。"}}, "applications": [{"type": "number", "prompt": {"en": "Beginning WIP $100, costs added $900, ending WIP $200. Find COGM.", "zh": "期初 WIP 100、本期投入 900、期末 WIP 200，求 COGM。"}, "answer": 800, "solution": {"en": "100 + 900 − 200 = 800.", "zh": "100 + 900 − 200 = 800。"}, "unit": "$", "tolerance": 0.01}, {"type": "number", "prompt": {"en": "Beginning RM $50, purchases $400, ending RM $70, indirect materials used $30. Find DM used.", "zh": "期初 RM 50、采购 400、期末 RM 70、间接材料耗用 30，求 DM 耗用。"}, "answer": 350, "solution": {"en": "All materials used = 50 + 400 − 70 = 380; DM = 380 − 30 = 350.", "zh": "总材料耗用 = 380；减去间接材料 30，DM = 350。"}, "unit": "$", "tolerance": 0.01}]}, {"id": "l1-behavior", "section": 1, "title": {"en": "Variable, fixed and mixed costs", "zh": "变动、固定及混合成本"}, "pages": "55–63", "body": ["在相关范围内，变动成本总额随业务量同比变化，单位变动成本不变；固定成本总额不变，单位固定成本随业务量增加而下降。", "混合成本含固定项 a 和每单位变动项 b：Y = a + bX。先找真正驱动成本的业务量，例如机器小时，而不是自动用销量。", "约束性固定成本 committed 如长期厂房投资，短期难改；酌量性固定成本 discretionary 如年度广告预算，可由管理者短期调整。跨越容量区间后固定成本可能阶梯式增加。"], "summary": "Within the relevant range, variable cost per unit and total fixed cost remain constant.", "formula": "Y = a + bX; Fixed cost per unit = a / X", "trap": "不要假定固定成本在所有产量下永远不变，也不要把单位固定成本当增量成本。", "example": {"type": "number", "prompt": {"en": "Monthly utility cost is $40 + $0.03 per kWh. At 2,000 kWh, find total cost.", "zh": "月电费 = 40 + 每度 0.03，使用 2,000 度，求总费用。"}, "answer": 100, "solution": {"en": "40 + .03 × 2,000 = 100.", "zh": "40 + .03 × 2,000 = 100。"}, "unit": "$", "tolerance": 0.01}, "concept": {"type": "choice", "prompt": {"en": "Within the relevant range, doubling output causes total fixed cost to:", "zh": "相关范围内产量翻倍，总固定成本将："}, "options": [{"en": "Stay constant", "zh": "不变"}, {"en": "Double", "zh": "翻倍"}, {"en": "Halve", "zh": "减半"}], "answer": 0, "solution": {"en": "Only the fixed cost per unit falls.", "zh": "变化的是单位固定成本，总额不变。"}}, "applications": [{"type": "number", "prompt": {"en": "Y = 500 + 4X. Find cost at X = 300.", "zh": "Y = 500 + 4X，X = 300 时求总成本。"}, "answer": 1700, "solution": {"en": "500 + 4 × 300 = 1,700.", "zh": "500 + 4 × 300 = 1,700。"}, "unit": "$", "tolerance": 0.01}, {"type": "number", "prompt": {"en": "Fixed rent $12,000 covers up to 2,000 units. At 1,500 units, find fixed cost per unit.", "zh": "固定租金 12,000 可支持最多 2,000 件，产量 1,500 时求单位固定成本。"}, "answer": 8, "solution": {"en": "12,000 / 1,500 = 8.", "zh": "12,000 / 1,500 = 8。"}, "unit": "$/unit", "tolerance": 0.01}]}, {"id": "l1-relevant", "section": 1, "title": {"en": "Differential, opportunity and sunk costs", "zh": "差量、机会与沉没成本"}, "pages": "67–72", "body": ["相关成本是未来且在方案间不同的成本；差量成本表示方案成本之差。不能仅凭 variable 或 fixed 判断相关性。", "机会成本是选择一个方案放弃的最佳替代收益，往往不记账但应纳入决策。产能满负荷时特殊订单可能挤出正常销售，失去的贡献毛益就是机会成本。", "沉没成本已发生且无法改变，对当前选择不相关。购票支出不可退款时，应比较未来体验与未来可变支出，而非“不能浪费已花的钱”。"], "summary": "Relevant costs differ between future alternatives. Sunk costs are irrelevant; opportunity costs can be relevant without a ledger entry.", "formula": "Incremental benefit − incremental outlay − opportunity cost", "trap": "满产时的机会成本通常是放弃的贡献毛益，不是机械地把全部正常收入当净损失。", "example": {"type": "number", "prompt": {"en": "An order earns $500 and adds $300 cost but displaces $150 contribution. Find net benefit.", "zh": "订单收入 500、增量成本 300、挤出贡献毛益 150，求净收益。"}, "answer": 50, "solution": {"en": "500 − 300 − 150 = 50.", "zh": "500 − 300 − 150 = 50。"}, "unit": "$", "tolerance": 0.01}, "concept": {"type": "choice", "prompt": {"en": "Which cost should be ignored in a current decision?", "zh": "当前决策应忽略哪项？"}, "options": [{"en": "Irrecoverable past research cost", "zh": "不可收回的历史研发成本"}, {"en": "Future avoidable cost", "zh": "未来可避免成本"}, {"en": "Forgone rental income", "zh": "放弃的租金收益"}], "answer": 0, "solution": {"en": "Past irrecoverable research cost is sunk.", "zh": "不可收回的历史研发成本是沉没成本。"}}, "applications": [{"type": "number", "prompt": {"en": "Using a building saves $900 rent elsewhere but sacrifices $600 rental income. Find net benefit.", "zh": "自用建筑节省其他租金 900，但放弃出租收入 600，求净收益。"}, "answer": 300, "solution": {"en": "900 − 600 = 300; the forgone rent is an opportunity cost.", "zh": "900 − 600 = 300；放弃租金是机会成本。"}, "unit": "$", "tolerance": 0.01}, {"type": "number", "prompt": {"en": "Past development $5,000 is unrecoverable. Further work costs $1,000 and yields $1,800. Find incremental benefit.", "zh": "历史研发 5,000 不可收回，继续投入 1,000 可获 1,800，求增量收益。"}, "answer": 800, "solution": {"en": "1,800 − 1,000 = 800. Ignore the $5,000 sunk cost.", "zh": "1,800 − 1,000 = 800，忽略沉没成本 5,000。"}, "unit": "$", "tolerance": 0.01}]}, {"id": "l1-labor", "section": 2, "title": {"en": "Idle time, overtime and fringe benefits", "zh": "闲置工时、加班溢价与福利"}, "pages": "73–76", "body": ["正常生产中因停电、缺料、机器故障产生的闲置人工通常计入 MOH。生产工人的正常工资可计入 DL，但加班溢价通常计入 MOH。", "例如正常工资 20/小时，加班支付 30/小时：额外的 10 是 premium，不是整笔 30 都是溢价。题目若说明特定订单导致加班或长期稳定加班，须按给定政策处理。", "福利 Fringe benefits 如保险、退休金，企业可能全部列入 MOH，也可能把直接工人的福利列入 DL；答题需注明采用的政策。"], "summary": "Idle time and overtime premiums are ordinarily overhead; fringe-benefit classification depends on policy.", "formula": "Overtime premium = Overtime hours × (Overtime rate − Normal rate)", "trap": "不要将加班全部工资和加班溢价混为一谈。", "example": {"type": "number", "prompt": {"en": "Normal rate $20; overtime rate $30; overtime 6 hours. Find premium.", "zh": "正常时薪 20，加班时薪 30，加班 6 小时，求溢价。"}, "answer": 60, "solution": {"en": "6 × (30 − 20) = 60.", "zh": "6 × (30 − 20) = 60。"}, "unit": "$", "tolerance": 0.01}, "concept": {"type": "choice", "prompt": {"en": "Ordinary factory idle-time wages are usually:", "zh": "通常工厂闲置工时工资归入："}, "options": [{"en": "Manufacturing overhead", "zh": "制造费用"}, {"en": "Direct materials", "zh": "直接材料"}, {"en": "Selling expense", "zh": "销售费用"}], "answer": 0, "solution": {"en": "They support production but cannot be traced to productive units.", "zh": "与生产有关，但不是可追溯的有效生产工时。"}}, "applications": [{"type": "number", "prompt": {"en": "Normal $18/hour; overtime $27/hour; 10 overtime hours. Find premium.", "zh": "正常 18/小时，加班 27/小时，共 10 小时，求加班溢价。"}, "answer": 90, "solution": {"en": "10 × (27 − 18) = 90.", "zh": "10 × (27 − 18) = 90。"}, "unit": "$", "tolerance": 0.01}, {"type": "number", "prompt": {"en": "A worker is idle for 4 hours at $25/hour due to a power failure. Find ordinary MOH charge.", "zh": "工人停电闲置 4 小时，时薪 25，通常计入 MOH 多少？"}, "answer": 100, "solution": {"en": "4 × 25 = 100.", "zh": "4 × 25 = 100。"}, "unit": "$", "tolerance": 0.01}]}], "exercises": [{"id": "l1-e1", "title": {"en": "Dorlane: classify costs and explain “at cost”", "zh": "Dorlane：成本分类与“按成本出售”"}, "prompt": {"en": "Dorlane produces 2,000 patio sets at full capacity. Annual costs ($): direct factory labor 118,000; advertising 50,000; factory supervision 40,000; factory property tax 3,500; sales commissions 80,000; factory insurance 2,500; office depreciation 4,000; factory equipment lease 12,000; indirect factory materials 6,000; factory building depreciation 10,000; administrative supplies 3,000; administrative salaries 60,000; direct materials 94,000; factory utilities 20,000.\n1. Classify each by behavior and by S&A / direct product / indirect product cost. Follow the tutorial assumption that utilities and administrative supplies are variable.\n2. Find total product cost and cost per set.\n3. Explain the effect of producing only 1,000 sets within the relevant range.\n4. Explain why a relative and the president may disagree on “at cost”; discuss opportunity cost at full capacity.", "zh": "Dorlane满负荷年产2,000套家具。全年成本（美元）：直接工厂人工118,000；广告50,000；工厂监督40,000；厂房房产税3,500；销售佣金80,000；工厂保险2,500；办公折旧4,000；工厂设备租赁12,000；间接材料6,000；厂房折旧10,000；行政用品3,000；行政工资60,000；直接材料94,000；工厂水电20,000。\n1. 分别按变动/固定，以及销售行政/直接产品/间接产品成本分类。按tutorial假定水电和行政用品为变动。\n2. 求产品总成本和每套成本。\n3. 相关范围内产量降至1,000套，每套成本如何变化？\n4. 解释亲属和总裁对“按成本出售”的分歧，并讨论满产下机会成本。"}, "solution": {"en": "1. Variable/direct product: labor 118,000, DM 94,000. Variable/indirect product: indirect materials 6,000, utilities 20,000. Variable/S&A: commissions 80,000, supplies 3,000. Fixed/indirect product: supervision 40,000, tax 3,500, insurance 2,500, lease 12,000, factory depreciation 10,000. Fixed/S&A: advertising 50,000, office depreciation 4,000, office salaries 60,000.\nTotals: variable 321,000; fixed 182,000; S&A 197,000; direct product 212,000; indirect product 94,000. Both classification dimensions total 503,000.\n2. Product cost = 306,000; per set = 153.\n3. Average cost rises because fixed manufacturing cost is spread over fewer units. Assuming proportional variable costs, variable manufacturing cost = 119/set, fixed manufacturing cost = 68,000, giving 187/set at 1,000 sets.\n4. The president may mean full manufacturing cost $153; the relative may mean DM only $47 or DM+DL $106. At full capacity, supplying the relative sacrifices normal-sale contribution. Relevant production cost plus lost contribution can justify the normal price. The opportunity cost itself is the foregone contribution, not automatically gross revenue.", "zh": "1. 变动/直接产品：人工118,000、DM94,000；变动/间接产品：间接材料6,000、水电20,000；变动/销售行政：佣金80,000、用品3,000。固定/间接产品：监督40,000、税3,500、保险2,500、租赁12,000、厂房折旧10,000；固定/销售行政：广告50,000、办公折旧4,000、行政工资60,000。\n汇总：变动321,000；固定182,000；销售行政197,000；直接产品212,000；间接产品94,000。两个分类维度均合计503,000。\n2. 产品总成本306,000；每套153。\n3. 固定制造成本分摊到更少件数，单位成本上升。若变动成本同比变化：变动制造119/套、固定制造68,000，产1,000套时为187/套。\n4. 总裁可能指完整制造成本153；亲属可能只指材料47或DM+DL106。满产时给亲属供货会挤出正常销售，损失正常贡献毛益；相关生产成本加机会成本可支持正常售价。机会成本本身是放弃贡献，不宜机械等同全部销售收入。"}, "cards": ["l1-mfg", "l1-behavior", "l1-relevant"], "source": "Tutorial 1 Q1，PDF pp.1–2；答案 pp.1–2；Excel Q1（重述 / Restated）"}, {"id": "l1-e2", "title": {"en": "Managerial vs financial accounting", "zh": "管理会计与财务会计"}, "prompt": {"en": "Preparing next year’s sales budget is:\n1. Control\n2. Planning\n3. Audit", "zh": "编制明年销售预算属于：\n1. 控制\n2. 规划\n3. 审计"}, "solution": {"en": "Planning\nA budget specifies how future goals will be achieved.", "zh": "规划\n预算说明未来目标如何实现。"}, "cards": ["l1-purpose"], "source": "原创基础题 / Original drill · 与模卡复测共享题目"}, {"id": "l1-e3", "title": {"en": "Value creation and human judgment", "zh": "价值创造与 AI 下的管理判断"}, "prompt": {"en": "Decentralized information should be designed around:\n1. Decision needs\n2. The largest possible report\n3. Past spending only", "zh": "分散化信息系统应围绕：\n1. 决策需要\n2. 尽可能大的报告\n3. 仅历史支出"}, "solution": {"en": "Decision needs\nRelevant information must reach the responsible decision maker.", "zh": "决策需要\n相关信息应到达负责决策的人。"}, "cards": ["l1-ai"], "source": "原创基础题 / Original drill · 与模卡复测共享题目"}, {"id": "l1-e4", "title": {"en": "Cost objects, direct and indirect costs", "zh": "成本对象、直接与间接成本"}, "prompt": {"en": "A dedicated product designer’s fixed salary can be direct to a product line.\n1. True\n2. False", "zh": "专门产品设计师的固定薪酬可以是产品线直接成本。\n1. 正确\n2. 错误"}, "solution": {"en": "True\nDirect and fixed describe separate dimensions.", "zh": "正确\n直接和固定属于不同分类维度。"}, "cards": ["l1-object"], "source": "原创基础题 / Original drill · 与模卡复测共享题目"}, {"id": "l1-e5", "title": {"en": "Manufacturing, prime and conversion costs", "zh": "制造成本、主要成本与加工成本"}, "prompt": {"en": "Prime cost is $240 and DL is $90. MOH is $70. Find total manufacturing cost.", "zh": "主要成本 240、DL 90、MOH 70，计算总制造成本。"}, "solution": {"en": "310 $\nDM = 240 − 90 = 150; total = 150 + 90 + 70 = 310.", "zh": "310 $\nDM = 240 − 90 = 150；总额 = 150 + 90 + 70 = 310。"}, "cards": ["l1-mfg"], "source": "原创基础题 / Original drill · 与模卡复测共享题目"}, {"id": "l1-e6", "title": {"en": "Product costs, period costs and inventory flow", "zh": "产品成本、期间成本与存货流转"}, "prompt": {"en": "Beginning RM $50, purchases $400, ending RM $70, indirect materials used $30. Find DM used.", "zh": "期初 RM 50、采购 400、期末 RM 70、间接材料耗用 30，求 DM 耗用。"}, "solution": {"en": "350 $\nAll materials used = 50 + 400 − 70 = 380; DM = 380 − 30 = 350.", "zh": "350 $\n总材料耗用 = 380；减去间接材料 30，DM = 350。"}, "cards": ["l1-flow"], "source": "原创基础题 / Original drill · 与模卡复测共享题目"}, {"id": "l1-e7", "title": {"en": "Variable, fixed and mixed costs", "zh": "变动、固定及混合成本"}, "prompt": {"en": "Fixed rent $12,000 covers up to 2,000 units. At 1,500 units, find fixed cost per unit.", "zh": "固定租金 12,000 可支持最多 2,000 件，产量 1,500 时求单位固定成本。"}, "solution": {"en": "8 $/unit\n12,000 / 1,500 = 8.", "zh": "8 $/unit\n12,000 / 1,500 = 8。"}, "cards": ["l1-behavior"], "source": "原创基础题 / Original drill · 与模卡复测共享题目"}, {"id": "l1-e8", "title": {"en": "Differential, opportunity and sunk costs", "zh": "差量、机会与沉没成本"}, "prompt": {"en": "Past development $5,000 is unrecoverable. Further work costs $1,000 and yields $1,800. Find incremental benefit.", "zh": "历史研发 5,000 不可收回，继续投入 1,000 可获 1,800，求增量收益。"}, "solution": {"en": "800 $\n1,800 − 1,000 = 800. Ignore the $5,000 sunk cost.", "zh": "800 $\n1,800 − 1,000 = 800，忽略沉没成本 5,000。"}, "cards": ["l1-relevant"], "source": "原创基础题 / Original drill · 与模卡复测共享题目"}, {"id": "l1-e9", "title": {"en": "Idle time, overtime and fringe benefits", "zh": "闲置工时、加班溢价与福利"}, "prompt": {"en": "A worker is idle for 4 hours at $25/hour due to a power failure. Find ordinary MOH charge.", "zh": "工人停电闲置 4 小时，时薪 25，通常计入 MOH 多少？"}, "solution": {"en": "100 $\n4 × 25 = 100.", "zh": "100 $\n4 × 25 = 100。"}, "cards": ["l1-labor"], "source": "原创基础题 / Original drill · 与模卡复测共享题目"}], "notes": [{"title": "分类须说明成本对象和工资行为", "body": "Lecture 1 PDF pp.65–66 对厂长与装配工资的标签较简略。相对于单件产品，厂长通常是间接人工/MOH；装配工资是否固定取决于按小时、件数还是固定月薪支付。Tutorial 1明确将直接人工列为变动，练习沿用该题假设。"}]}, {"id": "l2", "title": {"en": "Job & process costing", "zh": "分批与分步成本法"}, "subtitle": "沿成本流转，建立可核对的计算链。", "sections": ["2-1 产品与服务成本系统", "2-2 分批成本法", "2-3 分步成本法"], "cards": [{"id": "l2-system", "section": 0, "title": {"en": "Choosing a costing system", "zh": "选择成本系统"}, "pages": "8–16, 69–72, 132–134", "body": ["分批成本法用于不同客户或批次的异质产品，按 job 累积成本，再除以该 job 产量。分步成本法用于连续、大量同质产品，按部门或工序累积并平均。两者都处理 DM、DL、MOH，并使用 RM、WIP、FG 账户。", "服务企业也需要成本信息用于报价和控制，例如建筑设计项目、医疗服务；不应因为服务通常不能储存就认为无需成本系统。", "Operation costing 是混合系统：不同系列的材料分别追溯，共用工序的加工成本平均分配。AI 可自动归集和追踪，但成本对象、分配基础、WA/FIFO 政策仍须选择。"], "summary": "Job costing accumulates by job; process costing accumulates by department for homogeneous output. Operation costing combines both.", "formula": "Job unit cost = Job total cost / Units in job", "trap": "方法取决于生产流程和异质性，不只取决于公司大小。", "example": {"type": "choice", "prompt": {"en": "A custom wedding caterer most likely uses:", "zh": "定制婚宴服务最可能使用："}, "options": [{"en": "Job-order costing", "zh": "分批成本法"}, {"en": "Process costing only", "zh": "仅分步成本法"}], "answer": 0, "solution": {"en": "Each customer order has distinct requirements.", "zh": "各客户订单要求不同。"}}, "concept": {"type": "choice", "prompt": {"en": "Continuous identical paper production is best suited to:", "zh": "连续生产相同纸张适合："}, "options": [{"en": "Process costing", "zh": "分步成本法"}, {"en": "Job costing for each sheet", "zh": "每张纸单独分批"}], "answer": 0, "solution": {"en": "Homogeneous output permits departmental averaging.", "zh": "同质产出适合部门平均。"}}, "applications": [{"type": "choice", "prompt": {"en": "Different toy materials but shared molding and assembly suggest:", "zh": "玩具材料不同但共用成型装配流程，适合："}, "options": [{"en": "Operation costing", "zh": "混合成本法"}, {"en": "No cost system", "zh": "无需成本系统"}, {"en": "Financial reporting only", "zh": "仅财务报告"}], "answer": 0, "solution": {"en": "Trace differing materials, average common conversion.", "zh": "分别追溯材料，共同加工成本平均。"}}, {"type": "choice", "prompt": {"en": "Do job and process costing use the same basic inventory accounts?", "zh": "两种成本法使用相同基本存货账户吗？"}, "options": [{"en": "Yes", "zh": "是"}, {"en": "No", "zh": "否"}], "answer": 0, "solution": {"en": "Both use RM, WIP and FG.", "zh": "两者都使用 RM、WIP、FG。"}}]}, {"id": "l2-pohr", "section": 1, "title": {"en": "Predetermined overhead and job sheets", "zh": "预定制造费用分配率与批次成本单"}, "pages": "18–36, 39–42", "body": ["材料领用单追踪 DM，工时记录追踪 DL，批次成本单汇集 DM、DL 和 applied MOH。MOH 难以直接追溯，需选择能解释资源消耗的分配基础。", "期初预定率 POHR = 预计 MOH / 预计分配基础总量；本期某 job 分配额 = POHR × 该 job 实际使用基础量。分子若含固定和变动部分，先算 a + b × estimated activity。", "预定率让报价及时并减少季节性波动。批次平均单位成本含固定费用分摊，不等于多生产一件的边际成本。"], "summary": "Use estimated totals to set the rate, then actual job activity to apply overhead.", "formula": "POHR = Estimated MOH / Estimated base; Job cost = DM + DL + POHR × actual job base", "trap": "期初率用预计基础；分配到 job 时用实际基础。", "example": {"type": "number", "prompt": {"en": "Estimated MOH $640,000; estimated DLH 160,000. Find POHR.", "zh": "预计 MOH 640,000、DLH 160,000，求 POHR。"}, "answer": 4, "solution": {"en": "640,000 / 160,000 = $4 per DLH.", "zh": "640,000 / 160,000 = 每 DLH 4。"}, "unit": "$/DLH", "tolerance": 0.01}, "concept": {"type": "choice", "prompt": {"en": "Which base is used to APPLY the predetermined rate to a job?", "zh": "将预定率分配到 job 时用哪个基础？"}, "options": [{"en": "Actual activity of the job", "zh": "job 实际活动量"}, {"en": "Estimated activity of all jobs", "zh": "所有 job 预计活动量"}, {"en": "Actual total MOH", "zh": "实际 MOH 总额"}], "answer": 0, "solution": {"en": "The rate is fixed in advance; the quantity applied is actual job use.", "zh": "率事先确定，乘以该 job 实际用量。"}}, "applications": [{"type": "number", "prompt": {"en": "POHR $38/DLH; job DM $200 and 10 DLH at $15/hour. Find total job cost.", "zh": "POHR 38/DLH；DM 200，10 DLH，时薪 15，求 job 总成本。"}, "answer": 730, "solution": {"en": "200 + 10 × 15 + 10 × 38 = 730.", "zh": "200 + 150 + 380 = 730。"}, "unit": "$", "tolerance": 0.01}, {"type": "number", "prompt": {"en": "Fixed MOH $120,000 plus $3 per MH, estimated 40,000 MH. A job uses 100 MH, DM $200, DL $300. Find job cost.", "zh": "固定 MOH 120,000，变动 3/MH，预计 40,000 MH；job 用 100 MH、DM 200、DL 300，求总成本。"}, "answer": 1100, "solution": {"en": "POHR = (120,000 + 3 × 40,000)/40,000 = 6; job = 200 + 300 + 600 = 1,100.", "zh": "POHR = 6；总成本 = 200 + 300 + 600 = 1,100。"}, "unit": "$", "tolerance": 0.01}]}, {"id": "l2-entries", "section": 1, "title": {"en": "Cost flows and journal entries", "zh": "成本流转与会计分录"}, "pages": "43–57", "body": ["购入材料：Dr RM / Cr AP。领用 DM：Dr WIP / Cr RM；间接材料：Dr MOH / Cr RM。直接人工借记 WIP，间接人工借记 MOH，贷记应付工资。", "实际其他制造费用借记 MOH；分配制造费用 Dr WIP / Cr MOH。MOH 是清算账户：借方实际、贷方分配，期末差额需要处理。", "完工 Dr FG / Cr WIP；销售需两笔：Dr AR / Cr Sales，以及 Dr COGS / Cr FG。未完工留在 WIP，未售出完工品留在 FG。"], "summary": "Actual overhead is debited to MOH; applied overhead is credited to MOH and debited to WIP.", "formula": "RM → WIP → FG → COGS", "trap": "完工不等于销售；记录收入并不会自动结转成本。", "example": {"type": "number", "prompt": {"en": "A completed job costs $10,000 for 100 units. Sell 60 units. Find COGS.", "zh": "完工批次 100 件成本 10,000，售出 60 件，求 COGS。"}, "answer": 6000, "solution": {"en": "Unit cost = 100; COGS = 60 × 100 = 6,000.", "zh": "单位成本 100；COGS = 6,000。"}, "unit": "$", "tolerance": 0.01}, "concept": {"type": "choice", "prompt": {"en": "Applying MOH requires:", "zh": "分配 MOH 的分录是："}, "options": [{"en": "Dr WIP, Cr MOH", "zh": "借 WIP，贷 MOH"}, {"en": "Dr MOH, Cr WIP", "zh": "借 MOH，贷 WIP"}, {"en": "Dr Sales, Cr FG", "zh": "借 Sales，贷 FG"}], "answer": 0, "solution": {"en": "Application adds cost to production.", "zh": "费用分配增加在产品成本。"}}, "applications": [{"type": "number", "prompt": {"en": "A job has beginning WIP $30,000; added DM $30,000, DL $35,000, applied MOH $60,000. Find completed cost.", "zh": "job 期初 WIP 30,000，新增 DM 30,000、DL 35,000、MOH 60,000，求完工成本。"}, "answer": 155000, "solution": {"en": "30,000 + 30,000 + 35,000 + 60,000 = 155,000.", "zh": "期初成本必须保留，合计 155,000。"}, "unit": "$", "tolerance": 0.01}, {"type": "number", "prompt": {"en": "A job of 200 units costs $24,000. 150 are sold. Find ending FG.", "zh": "200 件成本 24,000，售出 150 件，求期末 FG。"}, "answer": 6000, "solution": {"en": "50 unsold × $120 = $6,000.", "zh": "未售 50 件 × 单位成本 120 = 6,000。"}, "unit": "$", "tolerance": 0.01}]}, {"id": "l2-oh", "section": 1, "title": {"en": "Underapplied and overapplied overhead", "zh": "少分配与多分配制造费用"}, "pages": "58–68", "body": ["实际 MOH > 分配 MOH 是 underapplied，MOH 借方余额；实际 < 分配是 overapplied，贷方余额。差异可能来自预算成本、活动量或基础选择。", "简化处理结转 COGS：少分配增加 COGS、减少利润；多分配减少 COGS、增加利润。若分摊到 WIP、FG、COGS，依题目要求，课件按各账户内已分配 MOH 比例，而不是随意按总余额。", "结转后 MOH 清零。核对差异方向，再写借贷，避免靠背诵符号。"], "summary": "Underapplied overhead increases COGS when closed out; overapplied overhead decreases it.", "formula": "Underapplied amount = Actual MOH − Applied MOH", "trap": "分摊基数是各账户中的 applied MOH，除非题目另有指定。", "example": {"type": "number", "prompt": {"en": "Actual MOH $1,210,000; rate $4; actual MH 290,000. Find underapplied MOH.", "zh": "实际 MOH 1,210,000，率 4，实际 MH 290,000，求少分配额。"}, "answer": 50000, "solution": {"en": "Applied = 1,160,000; actual − applied = 50,000.", "zh": "分配 1,160,000；少分配 50,000。"}, "unit": "$", "tolerance": 0.01}, "concept": {"type": "choice", "prompt": {"en": "Closing overapplied overhead to COGS will:", "zh": "多分配 MOH 结转 COGS 会："}, "options": [{"en": "Reduce COGS", "zh": "减少 COGS"}, {"en": "Increase COGS", "zh": "增加 COGS"}, {"en": "Increase WIP", "zh": "增加 WIP"}], "answer": 0, "solution": {"en": "Previously assigned costs exceeded actual costs.", "zh": "先前分配成本超过实际，因此冲减成本。"}}, "applications": [{"type": "number", "prompt": {"en": "Overapplied MOH $30,000. WIP/FG/COGS contain applied MOH $68,000/$204,000/$408,000. How much reduces COGS?", "zh": "多分配 30,000；WIP/FG/COGS 含分配 MOH 68,000/204,000/408,000，COGS 减少多少？"}, "answer": 18000, "solution": {"en": "30,000 × 408,000 / 680,000 = 18,000.", "zh": "30,000 × 60% = 18,000。"}, "unit": "$", "tolerance": 0.01}, {"type": "number", "prompt": {"en": "Unadjusted COGS $1,200,000 and underapplied MOH $40,000, all closed to COGS. Find adjusted COGS.", "zh": "未调整 COGS 1,200,000，少分配 40,000 全部结转 COGS，求调整后金额。"}, "answer": 1240000, "solution": {"en": "1,200,000 + 40,000 = 1,240,000.", "zh": "少分配增加 COGS：1,240,000。"}, "unit": "$", "tolerance": 0.01}]}, {"id": "l2-eu", "section": 2, "title": {"en": "Physical flow and equivalent units", "zh": "实物数量与约当产量"}, "pages": "72–90", "body": ["分步成本法为每个加工部门建立 WIP。转出 A 部门的成本借记 WIP-B、贷记 WIP-A；末部门完工转 FG。", "先核对实物：期初 WIP + 本期投入 = 转出 + 期末 WIP。约当产量 EU 把部分完工数量换成完整工作量，必须对材料、加工成本分别算。", "材料可能在开始或末尾一次投入，加工成本通常持续发生。400 件已投入全部材料、加工 20%，材料 EU 400、加工 EU 80。不要用同一完成度乘所有成本。"], "summary": "Equivalent units measure work, not physical units. Completion percentages differ by cost category.", "formula": "EU in ending WIP = Physical units × Completion %", "trap": "期末实物 600 件不一定等于材料 EU 600。", "example": {"type": "number", "prompt": {"en": "400 units are 20% complete for conversion. Find conversion EU.", "zh": "400 件加工完成 20%，求加工 EU。"}, "answer": 80, "solution": {"en": "400 × 20% = 80.", "zh": "400 × 20% = 80。"}, "unit": "EU", "tolerance": 0.01}, "concept": {"type": "choice", "prompt": {"en": "Materials added at the END: ending WIP is 35% converted. Material completion is:", "zh": "材料在末尾加入，期末 WIP 加工 35%，材料完成度为："}, "options": [{"en": "0%", "zh": "0%"}, {"en": "35%", "zh": "35%"}, {"en": "100%", "zh": "100%"}], "answer": 0, "solution": {"en": "Ending units have not reached material addition.", "zh": "尚未到材料投入时点。"}}, "applications": [{"type": "number", "prompt": {"en": "Beginning units 300, started 6,000, ending 900. Find transferred-out units.", "zh": "期初 300，投入 6,000，期末 900，求转出数量。"}, "answer": 5400, "solution": {"en": "300 + 6,000 − 900 = 5,400.", "zh": "300 + 6,000 − 900 = 5,400。"}, "unit": "units", "tolerance": 0.01}, {"type": "number", "prompt": {"en": "Ending WIP 600 units, conversion 35% complete. Find ending conversion EU.", "zh": "期末 WIP 600 件，加工 35%，求期末加工 EU。"}, "answer": 210, "solution": {"en": "600 × .35 = 210.", "zh": "600 × .35 = 210。"}, "unit": "EU", "tolerance": 0.01}]}, {"id": "l2-wa", "section": 2, "title": {"en": "Weighted-average process costing", "zh": "加权平均分步成本法"}, "pages": "90–110, 135–142", "body": ["WA 把期初与本期成本混合。步骤一：转出数量 + 期末 EU；步骤二：期初成本 + 本期投入成本，除以 WA EU；步骤三：分配给转出及期末；步骤四：成本勾稽。", "期初完成百分比不从 WA EU 中扣除，因为分子也包含前期成本。转出的每件对本部门通常按 100% 完工处理。", "材料与加工分别算单位 EU 成本，期末 WIP = 材料 EU × 材料率 + 加工 EU × 加工率。不要用总实物数直接分所有成本。"], "summary": "WA combines beginning and current costs and divides by transferred-out units plus ending equivalent units.", "formula": "WA rate = (Beginning cost + Added cost) / (Transferred units + Ending EU)", "trap": "不能把 WA 的成本分子与 FIFO 的 EU 分母混用。", "example": {"type": "number", "prompt": {"en": "Transferred 5,400; ending 900 at 60% materials. Find WA material EU.", "zh": "转出 5,400；期末 900，材料完成 60%，求 WA 材料 EU。"}, "answer": 5940, "solution": {"en": "5,400 + 900 × .60 = 5,940.", "zh": "5,400 + 540 = 5,940。"}, "unit": "EU", "tolerance": 0.01}, "concept": {"type": "choice", "prompt": {"en": "Does WA include beginning WIP cost in its cost-per-EU numerator?", "zh": "WA 单位 EU 成本分子含期初 WIP 成本吗？"}, "options": [{"en": "Yes", "zh": "是"}, {"en": "No", "zh": "否"}], "answer": 0, "solution": {"en": "It pools costs from both periods.", "zh": "WA 将两期成本合并。"}}, "applications": [{"type": "number", "prompt": {"en": "Beginning material cost $6,119; added $118,621; WA EU 5,940. Find material cost per EU.", "zh": "期初材料成本 6,119，新增 118,621，WA EU 5,940，求单位 EU 材料成本。"}, "answer": 21, "solution": {"en": "124,740 / 5,940 = 21.", "zh": "124,740 / 5,940 = 21。"}, "unit": "$/EU", "tolerance": 0.01}, {"type": "number", "prompt": {"en": "End material EU 540 at $21, conversion EU 270 at $15. Find ending WIP cost.", "zh": "期末材料 EU 540、率 21；加工 EU 270、率 15，求期末 WIP。"}, "answer": 15390, "solution": {"en": "540 × 21 + 270 × 15 = 15,390.", "zh": "11,340 + 4,050 = 15,390。"}, "unit": "$", "tolerance": 0.01}]}, {"id": "l2-fifo", "section": 2, "title": {"en": "FIFO equivalent units and current cost rates", "zh": "FIFO 约当产量及本期成本率"}, "pages": "111–122", "body": ["FIFO 只计量本期完成的工作。EU = 完成期初尚未完成部分 + 本期开始并完成 + 期末 EU。若期初全部先完成，本期开始并完成 = 转出 − 期初数量。", "等价写法：FIFO EU = 转出 + 期末 EU − 期初已完成 EU。材料与加工各自扣除期初已完成工作量。", "成本率分子只用本期新增成本。FIFO 更能反映当期成本变化；WA 的低成本期初存货可能掩盖本期上涨。"], "summary": "FIFO separates current-period work and cost from prior-period work and cost.", "formula": "FIFO EU = Transferred + Ending EU − Beginning EU; rate = Current added cost / FIFO EU", "trap": "期初材料 100% 完成，则本期完成期初材料 EU 为 0。", "example": {"type": "number", "prompt": {"en": "Transferred 5,400; end 900 at 60%; beginning 300 at 40%. Find FIFO material EU.", "zh": "转出 5,400；期末 900 完成 60%；期初 300 完成 40%，求 FIFO 材料 EU。"}, "answer": 5820, "solution": {"en": "5,400 + 540 − 120 = 5,820.", "zh": "5,400 + 540 − 120 = 5,820。"}, "unit": "EU", "tolerance": 0.01}, "concept": {"type": "choice", "prompt": {"en": "FIFO cost per EU includes which costs?", "zh": "FIFO 单位 EU 成本包含哪些成本？"}, "options": [{"en": "Current added costs only", "zh": "仅本期新增成本"}, {"en": "Beginning costs only", "zh": "仅期初成本"}, {"en": "All historical costs", "zh": "全部历史成本"}], "answer": 0, "solution": {"en": "The denominator measures current work, so use current cost.", "zh": "分母是本期工作量，分子对应本期成本。"}}, "applications": [{"type": "number", "prompt": {"en": "Beginning 10,000 at 30% conversion; transferred 160,000; end 20,000 at 40%. Find FIFO conversion EU.", "zh": "期初 10,000 加工 30%；转出 160,000；期末 20,000 加工 40%，求 FIFO 加工 EU。"}, "answer": 165000, "solution": {"en": "160,000 + 8,000 − 3,000 = 165,000.", "zh": "160,000 + 8,000 − 3,000 = 165,000。"}, "unit": "EU", "tolerance": 0.01}, {"type": "number", "prompt": {"en": "Current conversion cost $244,200; FIFO conversion EU 165,000. Find cost per EU.", "zh": "本期加工成本 244,200；FIFO 加工 EU 165,000，求单位 EU 成本。"}, "answer": 1.48, "solution": {"en": "244,200 / 165,000 = 1.48.", "zh": "244,200 / 165,000 = 1.48。"}, "unit": "$/EU", "tolerance": 0.01}]}, {"id": "l2-assign", "section": 2, "title": {"en": "FIFO assignment and cost reconciliation", "zh": "FIFO 成本分配与勾稽"}, "pages": "123–131, 143–147", "body": ["FIFO 转出成本分三块：期初已累计成本 + 本期完成期初的成本 + 本期开始并完成的成本。期初已经发生的成本不能丢掉，也不能重新按本期率计价。", "期末成本 = 各成本类别期末 EU × 本期成本率。最后核对：期初成本 + 本期新增 = 转出成本 + 期末成本。", "保留中间精度，最后再舍入；逐行舍入可能有 1 元差异，应说明。WA 与 FIFO 比较要同时解释成本和产量口径。"], "summary": "FIFO transferred-out cost preserves beginning cost and adds only the current work needed to finish it.", "formula": "Beginning cost + Added cost = Transferred cost + Ending WIP cost", "trap": "只算“本期率 × 全部转出数量”会漏掉或错误重算期初成本。", "example": {"type": "number", "prompt": {"en": "Beginning cost $13,400; finish-beginning cost $10,360; started/completed cost $345,000. Find FIFO transferred cost.", "zh": "期初成本 13,400；完成期初新增 10,360；本期开始并完成 345,000，求 FIFO 转出成本。"}, "answer": 368760, "solution": {"en": "13,400 + 10,360 + 345,000 = 368,760.", "zh": "13,400 + 10,360 + 345,000 = 368,760。"}, "unit": "$", "tolerance": 0.01}, "concept": {"type": "choice", "prompt": {"en": "A cost reconciliation report must compare:", "zh": "成本勾稽报告应比较："}, "options": [{"en": "Costs to account for and costs accounted for", "zh": "待分配成本与已分配成本"}, {"en": "Sales and cash", "zh": "销售和现金"}, {"en": "Revenue and purchases only", "zh": "仅收入和采购"}], "answer": 0, "solution": {"en": "All input cost must be assigned to transferred units or WIP.", "zh": "投入成本全部分配到转出与期末 WIP。"}}, "applications": [{"type": "number", "prompt": {"en": "Total cost $397,000; ending WIP $28,240. Find transferred cost.", "zh": "总成本 397,000，期末 WIP 28,240，求转出成本。"}, "answer": 368760, "solution": {"en": "397,000 − 28,240 = 368,760.", "zh": "397,000 − 28,240 = 368,760。"}, "unit": "$", "tolerance": 0.01}, {"type": "number", "prompt": {"en": "End materials EU 720 at $6.30; conversion EU 160 at $26.90. Find ending WIP.", "zh": "期末材料 EU 720、率 6.30；加工 EU 160、率 26.90，求期末 WIP。"}, "answer": 8840, "solution": {"en": "720 × 6.3 + 160 × 26.9 = 8,840.", "zh": "4,536 + 4,304 = 8,840。"}, "unit": "$", "tolerance": 0.01}]}, {"id": "l2-transfer", "section": 2, "title": {"en": "Transferred-in costs", "zh": "转入成本的独立核算"}, "pages": "79–84; Tutorial 1 Q3", "body": ["后续部门应单独列 transferred-in costs，它代表上一部门已完成并转来的成本，不等于本部门新增材料。", "某单位进入本部门时，相对上一部门的工作通常已 100% 完成，因此本部门期末 WIP 的转入成本完成度为 100%，即使本部门材料尚未投入。", "Tutorial 1 Q3：转出 1,800、期末 600；WA 转入 EU 2,400，材料 EU 1,800，加工 EU 2,010。三类成本分别算率，再分别分配。"], "summary": "Transferred-in costs are a separate category; units already in the receiving department are 100% complete for the prior department’s work.", "formula": "WA transferred-in EU = Transferred-out units + Ending physical units", "trap": "本部门加工 35% 不意味着转入成本也只完成 35%。", "example": {"type": "number", "prompt": {"en": "Transferred-in cost $22,008; transferred 1,800 and ending 600. Find WA transferred-in rate.", "zh": "转入总成本 22,008，转出 1,800，期末 600，求 WA 转入成本率。"}, "answer": 9.17, "solution": {"en": "22,008 / 2,400 = 9.17.", "zh": "22,008 / 2,400 = 9.17。"}, "unit": "$/EU", "tolerance": 0.01}, "concept": {"type": "choice", "prompt": {"en": "Ending WIP has received no final-stage materials. Can it still have transferred-in cost?", "zh": "期末 WIP 尚未加入本部门末端材料，是否仍有转入成本？"}, "options": [{"en": "Yes", "zh": "是"}, {"en": "No", "zh": "否"}], "answer": 0, "solution": {"en": "It already carries work from the previous department.", "zh": "已承接上一部门完成的工作成本。"}}, "applications": [{"type": "number", "prompt": {"en": "End 600 units: transferred rate $9.17; material 0%; conversion 35% at $8. Find total ending cost.", "zh": "期末 600 件：转入率 9.17；材料 0%；加工 35%、率 8，求期末总成本。"}, "answer": 7182, "solution": {"en": "600 × 9.17 + 600 × .35 × 8 = 7,182.", "zh": "5,502 + 1,680 = 7,182。"}, "unit": "$", "tolerance": 0.01}, {"type": "number", "prompt": {"en": "Transferred-in, materials and conversion rates are $9.17, $4.55 and $8. Find cost of 1,800 finished units.", "zh": "转入、材料、加工率分别 9.17、4.55、8，求 1,800 完工件成本。"}, "answer": 39096, "solution": {"en": "1,800 × (9.17 + 4.55 + 8) = 39,096.", "zh": "1,800 × 21.72 = 39,096。"}, "unit": "$", "tolerance": 0.01}]}], "exercises": [{"id": "l2-e1", "title": {"en": "Gitano: overhead, COGM and COGS", "zh": "Gitano：制造费用、完工与销售成本"}, "prompt": {"en": "Estimated MOH $800,000; estimated DM usage $500,000. Allocate on DM USED. Actual purchases $510,000, DL $90,000; actual MOH: indirect labor $170,000, property tax $48,000, depreciation $260,000, maintenance $95,000, insurance $7,000, rent $180,000. Beginning/ending inventories: RM $20,000/$80,000; WIP $150,000/$70,000; FG $260,000/$400,000. All materials used are direct.\nFind (1) POHR, (2) under/overapplied MOH, (3) COGM, (4) unadjusted COGS and disposal alternatives, (5) adjusted COGS if all variance is closed to COGS.", "zh": "预计MOH800,000、预计DM耗用500,000，按DM实际耗用分配。实际采购510,000、DL90,000；实际MOH：间接人工170,000、税48,000、折旧260,000、维护95,000、保险7,000、租金180,000。期初/期末：RM20,000/80,000；WIP150,000/70,000；FG260,000/400,000。材料全部直接。\n求（1）预定率（2）少/多分配（3）COGM（4）未调整COGS及差异处理（5）全部差异结转COGS后的金额。"}, "solution": {"en": "1. POHR = 800,000/500,000 = 160% of DM used.\n2. DM used = 20,000+510,000−80,000 = 450,000. Applied MOH = 720,000. Actual MOH = 760,000. Underapplied = 40,000.\n3. Manufacturing costs added = 450,000+90,000+720,000 = 1,260,000. COGM = 150,000+1,260,000−70,000 = 1,340,000.\n4. COGS = 260,000+1,340,000−400,000 = 1,200,000. Close variance to COGS, or allocate among WIP/FG/COGS based on applied MOH contained in them.\n5. Adjusted COGS = 1,240,000. Dr COGS 40,000; Cr MOH 40,000.", "zh": "1. 800,000/500,000 = DM耗用的160%。\n2. DM耗用20,000+510,000−80,000=450,000；分配MOH720,000；实际MOH760,000；少分配40,000。\n3. 本期制造投入450,000+90,000+720,000=1,260,000；COGM150,000+1,260,000−70,000=1,340,000。\n4. 未调整COGS260,000+1,340,000−400,000=1,200,000。差异可全部结转COGS或按各账户内分配MOH比例分到WIP/FG/COGS。\n5. 调整后COGS1,240,000；借COGS40,000、贷MOH40,000。"}, "cards": ["l2-pohr", "l2-entries", "l2-oh"], "source": "Tutorial 1 Q2，题目 p.2；答案 pp.3–5；Excel Q2（重述 / Restated；第5问为补充）"}, {"id": "l2-e2", "title": {"en": "Provost: weighted average with transferred-in cost", "zh": "Provost：含转入成本的加权平均"}, "prompt": {"en": "Finishing department uses WA. Beginning WIP 450 units: transferred-in cost $4,068, materials $1,980, conversion $2,160 (materials 100%, conversion 60%). Received 1,950 units with transferred-in cost $17,940. Added materials $6,210 and conversion $13,920. Transferred out 1,800; ending WIP 600 (materials 0%, conversion 35%). An assistant charged all $46,278 to the 1,800 units ($25.71 each), leaving zero WIP.\nCompute EUs and rates for all three categories, costs transferred and ending WIP, and explain the error.", "zh": "Finishing部门用WA。期初450件：转入成本4,068、材料1,980、加工2,160（材料100%、加工60%）。本期转入1,950件，成本17,940；新增材料6,210、加工13,920。转出1,800；期末600件（材料0%、加工35%）。助理将全部46,278分给1,800完工件，每件25.71，期末WIP记零。\n计算三类EU、成本率、转出和期末成本，并解释错误。"}, "solution": {"en": "Physical flow: 450+1,950 = 1,800+600.\nEU: transferred-in 2,400; materials 1,800; conversion 1,800+600×35%=2,010.\nCosts: 22,008 / 8,190 / 16,080. Rates: 9.17 / 4.55 / 8.00.\nEnding WIP: 600×9.17 + 0×4.55 + 210×8 = 7,182.\nTransferred: 1,800×(9.17+4.55+8) = 39,096, or $21.72/unit.\nReconcile 7,182+39,096=46,278. The assistant incorrectly assigned the cost of incomplete units to finished units. Ending materials are zero, but transferred-in and conversion costs are not zero.", "zh": "实物流：450+1,950=1,800+600。\nEU：转入2,400；材料1,800；加工1,800+600×35%=2,010。\n总成本分别22,008/8,190/16,080；单位率9.17/4.55/8.00。\n期末WIP=600×9.17+0×4.55+210×8=7,182。\n转出=1,800×21.72=39,096，每件21.72。\n勾稽7,182+39,096=46,278。助理把未完工产品的成本全部转给完工产品；期末材料为零不代表转入和加工成本也为零。"}, "cards": ["l2-wa", "l2-transfer", "l2-eu"], "source": "Tutorial 1 Q3，题目 p.3；答案 pp.5–6；Excel Q3（重述 / Restated）"}, {"id": "l2-e3", "title": {"en": "Selzik: complete FIFO production report", "zh": "Selzik：完整FIFO成本报告"}, "prompt": {"en": "Beginning WIP 10,000 units (materials 100%, conversion 30%) with materials $8,500 and conversion $4,900. Started 170,000; ending WIP 20,000 (materials 100%, conversion 40%). Added materials $139,400 and conversion $244,200. Materials enter at the start. Use FIFO.\nCompute transferred units, EUs, current rates, ending WIP, transferred costs by component and the reconciliation.", "zh": "期初WIP10,000件（材料100%、加工30%），成本材料8,500、加工4,900。本期投入170,000；期末20,000件（材料100%、加工40%）。新增材料139,400、加工244,200。材料开始加入，使用FIFO。\n求转出件数、EU、当期率、期末WIP、转出成本分解及勾稽。"}, "solution": {"en": "Transferred = 10,000+170,000−20,000 = 160,000; started and completed = 150,000.\nFIFO materials EU = 0+150,000+20,000 = 170,000; conversion EU = 7,000+150,000+8,000 = 165,000.\nRates: materials .82; conversion 1.48.\nEnding WIP = 20,000×.82 + 8,000×1.48 = 28,240.\nTransferred: beginning cost 13,400; finish beginning 7,000×1.48=10,360; started/completed 150,000×2.30=345,000. Total 368,760 (materials 131,500; conversion 237,260).\nReconcile 13,400+383,600 = 397,000 = 28,240+368,760.", "zh": "转出10,000+170,000−20,000=160,000；本期开始并完成150,000。\nFIFO材料EU=0+150,000+20,000=170,000；加工EU=7,000+150,000+8,000=165,000。\n材料率.82、加工率1.48。\n期末20,000×.82+8,000×1.48=28,240。\n转出：期初13,400 + 完成期初7,000×1.48=10,360 + 本期开始完成150,000×2.30=345,000；合计368,760（材料131,500；加工237,260）。\n勾稽13,400+383,600=397,000=28,240+368,760。"}, "cards": ["l2-fifo", "l2-assign"], "source": "Tutorial 1 Q4，题目 p.4；答案 pp.7–8；Excel Q4（重述 / Restated）"}, {"id": "l2-e4", "title": {"en": "Choosing a costing system", "zh": "选择成本系统"}, "prompt": {"en": "Do job and process costing use the same basic inventory accounts?\n1. Yes\n2. No", "zh": "两种成本法使用相同基本存货账户吗？\n1. 是\n2. 否"}, "solution": {"en": "Yes\nBoth use RM, WIP and FG.", "zh": "是\n两者都使用 RM、WIP、FG。"}, "cards": ["l2-system"], "source": "原创基础题 / Original drill · 与模卡复测共享题目"}, {"id": "l2-e5", "title": {"en": "Predetermined overhead and job sheets", "zh": "预定制造费用分配率与批次成本单"}, "prompt": {"en": "Fixed MOH $120,000 plus $3 per MH, estimated 40,000 MH. A job uses 100 MH, DM $200, DL $300. Find job cost.", "zh": "固定 MOH 120,000，变动 3/MH，预计 40,000 MH；job 用 100 MH、DM 200、DL 300，求总成本。"}, "solution": {"en": "1100 $\nPOHR = (120,000 + 3 × 40,000)/40,000 = 6; job = 200 + 300 + 600 = 1,100.", "zh": "1100 $\nPOHR = 6；总成本 = 200 + 300 + 600 = 1,100。"}, "cards": ["l2-pohr"], "source": "原创基础题 / Original drill · 与模卡复测共享题目"}, {"id": "l2-e6", "title": {"en": "Cost flows and journal entries", "zh": "成本流转与会计分录"}, "prompt": {"en": "A job of 200 units costs $24,000. 150 are sold. Find ending FG.", "zh": "200 件成本 24,000，售出 150 件，求期末 FG。"}, "solution": {"en": "6000 $\n50 unsold × $120 = $6,000.", "zh": "6000 $\n未售 50 件 × 单位成本 120 = 6,000。"}, "cards": ["l2-entries"], "source": "原创基础题 / Original drill · 与模卡复测共享题目"}, {"id": "l2-e7", "title": {"en": "Underapplied and overapplied overhead", "zh": "少分配与多分配制造费用"}, "prompt": {"en": "Unadjusted COGS $1,200,000 and underapplied MOH $40,000, all closed to COGS. Find adjusted COGS.", "zh": "未调整 COGS 1,200,000，少分配 40,000 全部结转 COGS，求调整后金额。"}, "solution": {"en": "1240000 $\n1,200,000 + 40,000 = 1,240,000.", "zh": "1240000 $\n少分配增加 COGS：1,240,000。"}, "cards": ["l2-oh"], "source": "原创基础题 / Original drill · 与模卡复测共享题目"}, {"id": "l2-e8", "title": {"en": "Physical flow and equivalent units", "zh": "实物数量与约当产量"}, "prompt": {"en": "Ending WIP 600 units, conversion 35% complete. Find ending conversion EU.", "zh": "期末 WIP 600 件，加工 35%，求期末加工 EU。"}, "solution": {"en": "210 EU\n600 × .35 = 210.", "zh": "210 EU\n600 × .35 = 210。"}, "cards": ["l2-eu"], "source": "原创基础题 / Original drill · 与模卡复测共享题目"}, {"id": "l2-e9", "title": {"en": "Weighted-average process costing", "zh": "加权平均分步成本法"}, "prompt": {"en": "End material EU 540 at $21, conversion EU 270 at $15. Find ending WIP cost.", "zh": "期末材料 EU 540、率 21；加工 EU 270、率 15，求期末 WIP。"}, "solution": {"en": "15390 $\n540 × 21 + 270 × 15 = 15,390.", "zh": "15390 $\n11,340 + 4,050 = 15,390。"}, "cards": ["l2-wa"], "source": "原创基础题 / Original drill · 与模卡复测共享题目"}, {"id": "l2-e10", "title": {"en": "FIFO equivalent units and current cost rates", "zh": "FIFO 约当产量及本期成本率"}, "prompt": {"en": "Current conversion cost $244,200; FIFO conversion EU 165,000. Find cost per EU.", "zh": "本期加工成本 244,200；FIFO 加工 EU 165,000，求单位 EU 成本。"}, "solution": {"en": "1.48 $/EU\n244,200 / 165,000 = 1.48.", "zh": "1.48 $/EU\n244,200 / 165,000 = 1.48。"}, "cards": ["l2-fifo"], "source": "原创基础题 / Original drill · 与模卡复测共享题目"}, {"id": "l2-e11", "title": {"en": "FIFO assignment and cost reconciliation", "zh": "FIFO 成本分配与勾稽"}, "prompt": {"en": "End materials EU 720 at $6.30; conversion EU 160 at $26.90. Find ending WIP.", "zh": "期末材料 EU 720、率 6.30；加工 EU 160、率 26.90，求期末 WIP。"}, "solution": {"en": "8840 $\n720 × 6.3 + 160 × 26.9 = 8,840.", "zh": "8840 $\n4,536 + 4,304 = 8,840。"}, "cards": ["l2-assign"], "source": "原创基础题 / Original drill · 与模卡复测共享题目"}, {"id": "l2-e12", "title": {"en": "Transferred-in costs", "zh": "转入成本的独立核算"}, "prompt": {"en": "Transferred-in, materials and conversion rates are $9.17, $4.55 and $8. Find cost of 1,800 finished units.", "zh": "转入、材料、加工率分别 9.17、4.55、8，求 1,800 完工件成本。"}, "solution": {"en": "39096 $\n1,800 × (9.17 + 4.55 + 8) = 39,096.", "zh": "39096 $\n1,800 × 21.72 = 39,096。"}, "cards": ["l2-transfer"], "source": "原创基础题 / Original drill · 与模卡复测共享题目"}], "notes": [{"title": "Ruger 期初 WIP 未计入课件结转数字", "body": "Lecture 2 PDF p.43给出Job A期初30,000；pp.46、48、52分别加DM30,000、DL35,000、MOH60,000，因此总额155,000。p.55写125,000，似遗漏期初30,000；同理Job B=20,000+25,000+30,000=75,000。若A共1,000件售750件，按完整数据COGS116,250、期末FG38,750，而p.57用125,000算93,750。复习采用保留期初余额的计算，并建议课堂核实。"}, {"title": "FIFO 公式与算例精度", "body": "PDF p.120提取出的公式可能仍显示期初成本，但p.122数表及FIFO定义只用本期新增成本。p.130的一元勾稽差异来自中间舍入。Sunspot pp.136–138：25,200+24,900=50,100，而p.138写50,000；24,900+238,700=263,600，而p.136写263,500。按所列输入总额为623,600，按课件答案为623,500，存在100差异。该例不直接用于自动判分，需向老师确认输入。"}, {"title": "背景案例与成本架构", "body": "PDF pp.2–7采购承诺与套期保值案例用来说明投入价格波动及成本滞后，不作为未来行情预测。pp.91、133强调AI追踪批次可改善数据，但混料、共同加工资源和成本对象选择仍需要会计政策。"}]}, {"id": "l3", "title": {"en": "Cost–volume–profit", "zh": "本量利分析"}, "subtitle": "用贡献毛益连接销量、风险与决策。", "sections": ["3-1 贡献式报表与模型", "3-2 决策、保本与目标利润", "3-3 风险与销售组合"], "cards": [{"id": "l3-cm", "section": 0, "title": {"en": "Contribution format and CM ratios", "zh": "贡献式报表与贡献毛益率"}, "pages": "2–4, 14–24, 33–40", "body": ["传统利润表按功能区分 COGS 和 S&A，毛利 = 销售 − COGS。贡献式按成本行为分类，CM = 销售 − 所有变动费用，既含变动制造费用，也含变动销售管理费用。", "CM 先覆盖固定费用，剩余才是 NOI。单位 CM = P − V；CM ratio = CM / Sales = (P − V)/P；变动费用率 = 1 − CM ratio。", "成本结构不变时，销售额变化 × CM ratio = CM 变化；固定成本不变时也是利润变化。"], "summary": "Contribution margin deducts all variable expenses, not just variable manufacturing costs.", "formula": "NOI = Q(P − V) − F = Sales × CMR − F", "trap": "贡献毛益不是毛利，也不是净利润。", "example": {"type": "number", "prompt": {"en": "Price $500, total variable cost $300/unit. Find CM ratio in percent.", "zh": "售价 500、单位全部变动成本 300，求 CM 率百分数。"}, "answer": 40, "solution": {"en": "(500 − 300)/500 × 100 = 40%.", "zh": "200/500 = 40%。"}, "unit": "%", "tolerance": 0.01}, "concept": {"type": "choice", "prompt": {"en": "Sales commissions that vary with units belong:", "zh": "随销量变化的佣金应列于："}, "options": [{"en": "Above CM as variable expense", "zh": "CM 之前的变动费用"}, {"en": "Only below CM as fixed", "zh": "仅 CM 之后的固定费用"}, {"en": "Inventory", "zh": "存货"}], "answer": 0, "solution": {"en": "All variable expenses are deducted before CM.", "zh": "所有变动费用均在 CM 前扣除。"}}, "applications": [{"type": "number", "prompt": {"en": "Sales $200,000; variable expense ratio 65%; fixed expenses $50,000. Find NOI.", "zh": "销售 200,000，变动费用率 65%，固定费用 50,000，求 NOI。"}, "answer": 20000, "solution": {"en": "CMR = 35%; NOI = 200,000 × .35 − 50,000 = 20,000.", "zh": "CMR 35%；NOI = 20,000。"}, "unit": "$", "tolerance": 0.01}, {"type": "number", "prompt": {"en": "CM ratio 40%, sales increase $50,000 and fixed costs unchanged. Find increase in NOI.", "zh": "CM 率 40%，销售增加 50,000，固定成本不变，求 NOI 增量。"}, "answer": 20000, "solution": {"en": "50,000 × .40 = 20,000.", "zh": "50,000 × .40 = 20,000。"}, "unit": "$", "tolerance": 0.01}]}, {"id": "l3-model", "section": 0, "title": {"en": "CVP assumptions and graphs", "zh": "CVP 假设与图形"}, "pages": "7–13, 25–32", "body": ["CVP 分析售价、销量、单位变动成本、固定成本和销售组合对利润的影响。标准模型在相关范围内假设售价和单位变动成本不变、总固定成本不变；多产品销售组合不变。课件制造业简化假设生产等于销售。", "CVP 图横轴销量，纵轴金额；收入线从原点出发，斜率 P；总成本线截距 F、斜率 V；相交点为保本。利润图截距 −F，斜率单位 CM。", "跨容量台阶、大幅降价改变需求、多期投资或组合改变时，应重新估计模型，不能机械外推。"], "summary": "CVP is a linear model valid within its relevant range; changing price or mix requires recalculation.", "formula": "Revenue = PQ; Total cost = F + VQ; Profit = (P − V)Q − F", "trap": "总成本线不从原点出发，除非 F = 0。", "example": {"type": "number", "prompt": {"en": "P $50, V $30, F $8,000. Find profit at Q = 500.", "zh": "P 50，V 30，F 8,000，Q 500 时求利润。"}, "answer": 2000, "solution": {"en": "(50 − 30) × 500 − 8,000 = 2,000.", "zh": "20 × 500 − 8,000 = 2,000。"}, "unit": "$", "tolerance": 0.01}, "concept": {"type": "choice", "prompt": {"en": "The vertical intercept of a profit graph is:", "zh": "利润图纵轴截距为："}, "options": [{"en": "−Fixed expenses", "zh": "负固定费用"}, {"en": "Selling price", "zh": "售价"}, {"en": "Zero always", "zh": "总是零"}], "answer": 0, "solution": {"en": "At zero sales, the firm loses its fixed expenses.", "zh": "销量为零时亏损固定费用。"}}, "applications": [{"type": "number", "prompt": {"en": "F $12,000 and V $8. Find total cost at Q = 1,000.", "zh": "F 12,000，V 8，Q 1,000，求总成本。"}, "answer": 20000, "solution": {"en": "12,000 + 8 × 1,000 = 20,000.", "zh": "12,000 + 8,000 = 20,000。"}, "unit": "$", "tolerance": 0.01}, {"type": "number", "prompt": {"en": "P $30, V $18. Find slope of the profit line.", "zh": "P 30，V 18，求利润线斜率。"}, "answer": 12, "solution": {"en": "Slope is unit CM = 30 − 18 = 12.", "zh": "斜率为单位 CM = 12。"}, "unit": "$/unit", "tolerance": 0.01}]}, {"id": "l3-change", "section": 1, "title": {"en": "Incremental scenario analysis", "zh": "多因素变化的增量分析"}, "pages": "41–53", "body": ["同时变动售价、变动成本、销量和固定费用时，最稳妥的方法是分别算新旧 NOI，再相减。不要只计算新增销量的 CM，因为降价或成本上涨可能影响全部销量。", "广告方案：增加 CM 减去增加固定广告费。材料升级：新单位 CM 乘新销量，减旧总 CM。工资改佣金：降低 F，但佣金加入每单位 V。", "列出 ΔP、ΔV、ΔQ、ΔF，说明其他条件不变。结果为正才表示该简化模型下有利，仍需考虑产能和需求假设。"], "summary": "Recompute the full contribution under the new scenario, then subtract changes in fixed expenses.", "formula": "ΔNOI = (P₁ − V₁)Q₁ − (P₀ − V₀)Q₀ − (F₁ − F₀)", "trap": "单位成本变化通常作用于全部新销量，不只新增销量。", "example": {"type": "number", "prompt": {"en": "Unit CM $200; advertising adds $10,000 and raises sales by 40 units. Find ΔNOI.", "zh": "单位 CM 200，广告增加 10,000，使销量增加 40，求 ΔNOI。"}, "answer": -2000, "solution": {"en": "40 × 200 − 10,000 = −2,000.", "zh": "8,000 − 10,000 = −2,000。"}, "unit": "$", "tolerance": 0.01}, "concept": {"type": "choice", "prompt": {"en": "A $10/unit cost increase applies to:", "zh": "单位成本上涨 10 应作用于："}, "options": [{"en": "All units under the new scenario", "zh": "新方案下全部单位"}, {"en": "Only extra units", "zh": "仅新增单位"}, {"en": "Only old inventory regardless of assumptions", "zh": "不论假设仅旧存货"}], "answer": 0, "solution": {"en": "The new rate applies to all affected new-scenario sales.", "zh": "新方案成本率应应用于全部受影响销量。"}}, "applications": [{"type": "number", "prompt": {"en": "Old P 500, V 300, Q 500. New V 310, Q 580; P and F unchanged. Find ΔNOI.", "zh": "旧 P 500、V 300、Q 500；新 V 310、Q 580；P、F 不变，求 ΔNOI。"}, "answer": 10200, "solution": {"en": "190 × 580 − 200 × 500 = 10,200.", "zh": "110,200 − 100,000 = 10,200。"}, "unit": "$", "tolerance": 0.01}, {"type": "number", "prompt": {"en": "Old P 500, V 300, Q 500. New P 480, Q 650, V 300; F rises 15,000. Find ΔNOI.", "zh": "旧 P 500、V 300、Q 500；新 P 480、Q 650、V 300；F 增加 15,000，求 ΔNOI。"}, "answer": 2000, "solution": {"en": "180 × 650 − 200 × 500 − 15,000 = 2,000.", "zh": "117,000 − 100,000 − 15,000 = 2,000。"}, "unit": "$", "tolerance": 0.01}]}, {"id": "l3-order", "section": 1, "title": {"en": "Special-order pricing", "zh": "特殊订单定价"}, "pages": "54–55", "body": ["有闲置产能且不影响原有销量、不增加固定费用时，额外订单报价需覆盖相关单位变动成本，加上每单位目标增量利润。原有固定费用通常不因该订单变化。", "若有额外设置费、运费、佣金或机会成本，须纳入。产能满载时的报价底线不能只用 V，因为订单可能挤出正常订单。", "这是短期增量分析，不意味着长期价格可以永久低于全部成本。"], "summary": "With spare capacity and no displacement, quote relevant variable cost plus required incremental profit per unit.", "formula": "Price = Relevant V + (Extra fixed cost + Opportunity cost + Target profit) / Order units", "trap": "必须明确闲置产能、无挤出和额外成本假设。", "example": {"type": "number", "prompt": {"en": "150 extra bikes; V $300; desired extra profit $3,000; no other effects. Find price.", "zh": "额外 150 辆，V 300，目标增量利润 3,000，无其他影响，求报价。"}, "answer": 320, "solution": {"en": "300 + 3,000/150 = 320.", "zh": "300 + 20 = 320。"}, "unit": "$/unit", "tolerance": 0.01}, "concept": {"type": "choice", "prompt": {"en": "Which condition can invalidate pricing at variable cost plus target margin?", "zh": "哪种情况会使“变动成本加目标利润”不足？"}, "options": [{"en": "Displacing profitable normal sales", "zh": "挤出有利正常销售"}, {"en": "Idle capacity", "zh": "闲置产能"}, {"en": "No extra fixed cost", "zh": "没有新增固定成本"}], "answer": 0, "solution": {"en": "Displacement creates an opportunity cost.", "zh": "挤出销售产生机会成本。"}}, "applications": [{"type": "number", "prompt": {"en": "Order 200 units, relevant V $12, extra setup $400, target profit $600. Find price.", "zh": "订单 200 件，相关 V 12，新增设置费 400，目标利润 600，求报价。"}, "answer": 17, "solution": {"en": "12 + (400 + 600)/200 = 17.", "zh": "12 + 5 = 17。"}, "unit": "$/unit", "tolerance": 0.01}, {"type": "number", "prompt": {"en": "Order 100 units, V $20, forgone contribution $500, target profit $300. Find price.", "zh": "订单 100 件，V 20，放弃贡献 500，目标利润 300，求报价。"}, "answer": 28, "solution": {"en": "20 + (500 + 300)/100 = 28.", "zh": "20 + 8 = 28。"}, "unit": "$/unit", "tolerance": 0.01}]}, {"id": "l3-be", "section": 1, "title": {"en": "Break-even and target profit", "zh": "保本与目标利润"}, "pages": "56–74", "body": ["保本令 NOI = 0：保本数量 = F / 单位 CM；保本销售额 = F / CMR。目标利润 T 时，分子改为 F + T。数量公式分母是每单位金额，销售额公式分母是比率。", "不可分割商品若要求至少达到目标，结果要向上取整，不是四舍五入。保本理论值可保留小数，并分别说明实际最低整数销量。", "先用未舍入的 CMR 算，最后舍入。若单位 CM ≤ 0 且 F > 0，增加销量无法用通常公式达到正利润。"], "summary": "Use unit CM for quantities and CM ratio for revenue; round indivisible required units upward.", "formula": "Qtarget = (F + T)/(P − V); Sales target = (F + T)/CMR", "trap": "课件咖啡保本 1,150 是近似；1,300/1.13 = 1,150.442…，实际至少 1,151 杯。", "example": {"type": "number", "prompt": {"en": "F $80,000; unit CM $200; target $100,000. Required units?", "zh": "F 80,000、单位 CM 200、目标利润 100,000，需要多少件？"}, "answer": 900, "solution": {"en": "(80,000 + 100,000)/200 = 900.", "zh": "180,000/200 = 900。"}, "unit": "units", "tolerance": 0.01}, "concept": {"type": "choice", "prompt": {"en": "Break-even dollar sales use which denominator?", "zh": "保本销售额的分母是什么？"}, "options": [{"en": "CM ratio", "zh": "CM 率"}, {"en": "Unit CM", "zh": "单位 CM"}, {"en": "Fixed cost per unit", "zh": "单位固定成本"}], "answer": 0, "solution": {"en": "Dividing fixed dollars by a ratio gives sales dollars.", "zh": "固定金额除以比率得到销售金额。"}}, "applications": [{"type": "number", "prompt": {"en": "F $1,300; P $1.49; V $.36. Minimum whole cups to avoid loss?", "zh": "F 1,300、P 1.49、V .36，至少卖多少整杯才能不亏？"}, "answer": 1151, "solution": {"en": "1,300/1.13 = 1,150.442…; round UP to 1,151.", "zh": "理论值 1,150.442…，向上取整为 1,151。"}, "unit": "cups", "tolerance": 0}, {"type": "number", "prompt": {"en": "F $210,000; unit CM $7; target $90,000. Minimum whole units?", "zh": "F 210,000，单位 CM 7，目标 90,000，至少多少整件？"}, "answer": 42858, "solution": {"en": "300,000/7 = 42,857.142…; round up to 42,858.", "zh": "300,000/7 后向上取整为 42,858。"}, "unit": "units", "tolerance": 0}]}, {"id": "l3-mos", "section": 2, "title": {"en": "Margin of safety", "zh": "安全边际"}, "pages": "76–81", "body": ["安全边际表示销售还能下降多少才到保本点。金额 = 实际或预算销售额 − 保本销售额；比率 = 安全边际 / 实际或预算销售额。单一产品可换算件数。", "分母是实际/预算销售，不是保本销售。负安全边际表示已经低于保本点。", "成本结构不变时 NOI = MOS dollars × CMR；可用来交叉核对。用理论保本数量和取整后的最低销量时，要说明精度口径。"], "summary": "Margin of safety measures the sales cushion above break-even.", "formula": "MOS% = (Sales − BE sales) / Sales", "trap": "安全边际率不是利润率；两者相差 CM 率。", "example": {"type": "number", "prompt": {"en": "Actual sales $250,000; BE sales $200,000. MOS percent?", "zh": "实际销售 250,000，保本 200,000，安全边际百分数？"}, "answer": 20, "solution": {"en": "(250,000 − 200,000)/250,000 = 20%.", "zh": "50,000/250,000 = 20%。"}, "unit": "%", "tolerance": 0.01}, "concept": {"type": "choice", "prompt": {"en": "A negative MOS means:", "zh": "安全边际为负意味着："}, "options": [{"en": "Sales are below break-even", "zh": "销售低于保本点"}, {"en": "No fixed cost", "zh": "没有固定成本"}, {"en": "Profit is guaranteed", "zh": "保证盈利"}], "answer": 0, "solution": {"en": "The firm has not reached the break-even sales level.", "zh": "企业尚未达到保本销售。"}}, "applications": [{"type": "number", "prompt": {"en": "Sales $750,000; BE sales $525,000. Find MOS dollars.", "zh": "销售 750,000、保本 525,000，求安全边际金额。"}, "answer": 225000, "solution": {"en": "750,000 − 525,000 = 225,000.", "zh": "750,000 − 525,000 = 225,000。"}, "unit": "$", "tolerance": 0.01}, {"type": "number", "prompt": {"en": "MOS dollars $50,000 and CMR 40%. Find NOI.", "zh": "安全边际金额 50,000、CM 率 40%，求 NOI。"}, "answer": 20000, "solution": {"en": "50,000 × .40 = 20,000.", "zh": "50,000 × .40 = 20,000。"}, "unit": "$", "tolerance": 0.01}]}, {"id": "l3-dol", "section": 2, "title": {"en": "Cost structure and operating leverage", "zh": "成本结构与经营杠杆"}, "pages": "82–95", "body": ["高固定、低变动结构在需求旺盛时可能更有利润，但销量下滑时风险更大；外包可能将部分固定支出变成按量支付，但需考虑质量与长期容量。", "DOL = CM / NOI，基于当前销量计算。成本与售价不变时，利润百分比变化 = DOL × 销量百分比变化。接近保本且盈利时 DOL 很大；NOI = 0 时比值未定义。", "在标准 CVP 模型且利润为正时 DOL = 1 / MOS%。随销量提高 DOL 通常下降，不是公司永久固定常数。"], "summary": "Operating leverage measures profit sensitivity at a specific sales level; it is undefined at zero operating income.", "formula": "DOL = CM / NOI; %ΔNOI = DOL × %ΔSales", "trap": "不能把当前 DOL 当作所有销量下都一样，也不能在亏损区机械解释为常规风险倍数。", "example": {"type": "number", "prompt": {"en": "CM $100,000, NOI $20,000. Find DOL.", "zh": "CM 100,000，NOI 20,000，求 DOL。"}, "answer": 5, "solution": {"en": "100,000/20,000 = 5.", "zh": "100,000/20,000 = 5。"}, "unit": "times", "tolerance": 0.01}, "concept": {"type": "choice", "prompt": {"en": "At exact break-even, DOL is:", "zh": "恰好保本时 DOL 为："}, "options": [{"en": "Undefined because NOI is zero", "zh": "NOI 为零，未定义"}, {"en": "Zero", "zh": "零"}, {"en": "Always one", "zh": "恒为一"}], "answer": 0, "solution": {"en": "Division by zero is undefined.", "zh": "分母为零，不能计算有限倍数。"}}, "applications": [{"type": "number", "prompt": {"en": "DOL 5 and sales rise 10% with unchanged structure. Profit rises by what percent?", "zh": "DOL 5，成本结构不变、销售上升 10%，利润上升百分数？"}, "answer": 50, "solution": {"en": "5 × 10% = 50%.", "zh": "5 × 10% = 50%。"}, "unit": "%", "tolerance": 0.01}, {"type": "number", "prompt": {"en": "MOS is 25% under the standard profitable CVP model. Find DOL.", "zh": "标准盈利 CVP 模型下 MOS 25%，求 DOL。"}, "answer": 4, "solution": {"en": "1/.25 = 4.", "zh": "1/.25 = 4。"}, "unit": "times", "tolerance": 0.01}]}, {"id": "l3-mix", "section": 2, "title": {"en": "Sales mix, commissions and multiproduct BE", "zh": "销售组合、佣金与多产品保本"}, "pages": "96–105", "body": ["多个产品的 CMR 不同，总体 CMR = 总 CM / 总销售额，也等于按销售额占比加权的 CMR。销售组合固定时，总体保本销售额 = 总 F / 总体 CMR。", "如果给的是销量组合，先构造组合包或按销量加权单位 CM；不能把销量占比直接乘收入 CM 率。销售往低贡献产品偏移可能降低利润，即使总销售额不变。", "课件 BE ratio = F / 总 CM = 1 − MOS%，用其乘各产品当前销售额可求固定组合下各产品保本收入。佣金按销售额可能鼓励高售价低 CM 产品，应关注激励一致性。"], "summary": "Weight CM ratios by revenue shares; the sales mix must stay constant for the computed break-even point.", "formula": "Weighted CMR = Σ(revenue share × product CMR); BE ratio = F / Total CM", "trap": "不要混用精确销售额比例和课件近似的 45%/55%。", "example": {"type": "number", "prompt": {"en": "Revenue mix A 40%, B 60%; CMR A 30%, B 50%. Weighted CMR percent?", "zh": "收入组合 A 40%、B 60%；CMR 分别 30%、50%，求加权 CMR 百分数。"}, "answer": 42, "solution": {"en": ".4 × .3 + .6 × .5 = .42.", "zh": ".12 + .30 = .42，即 42%。"}, "unit": "%", "tolerance": 0.01}, "concept": {"type": "choice", "prompt": {"en": "A commission based only on revenue can encourage:", "zh": "仅按销售收入发佣金可能鼓励："}, "options": [{"en": "High-price products with lower CM", "zh": "高售价但较低 CM 产品"}, {"en": "Always the highest CM", "zh": "总是最高 CM 产品"}, {"en": "Only fixed costs", "zh": "只有固定成本"}], "answer": 0, "solution": {"en": "Revenue and contribution incentives can diverge.", "zh": "收入激励和贡献毛益激励可能不一致。"}}, "applications": [{"type": "number", "prompt": {"en": "Total CM $265,000; sales $550,000; F $170,000. Find BE revenue to 2 decimals.", "zh": "总 CM 265,000，销售 550,000，F 170,000，求保本收入，保留两位。"}, "answer": 352830.19, "solution": {"en": "170,000 ÷ (265,000/550,000) = 352,830.1887.", "zh": "保持精确 CMR：352,830.19。"}, "unit": "$", "tolerance": 0.02}, {"type": "number", "prompt": {"en": "A/B revenue mix exactly 45%/55%; CMR 40%/55%; F $170,000. Find BE revenue.", "zh": "A/B 收入组合精确为 45%/55%，CMR 40%/55%，F 170,000，求保本收入。"}, "answer": 352331.61, "solution": {"en": "CMR = .45 × .4 + .55 × .55 = .4825; BE = 170,000/.4825 = 352,331.61.", "zh": "CMR = 48.25%；保本收入 352,331.61。"}, "unit": "$", "tolerance": 0.02}]}], "exercises": [{"id": "l3-e1", "title": {"en": "Northwood: CVP and automation", "zh": "Northwood：CVP与自动化方案"}, "prompt": {"en": "Basketball price $25; variable expense $15 (60% is direct labor); sales 30,000; F $210,000. Original sales $750,000, CM $300,000, NOI $90,000.\n1. Compute CMR, BE units and DOL.\n2. V rises by $3, price stays $25. Compute CMR and BE units.\n3. Under (2), find minimum whole sales units for NOI $90,000.\n4. Under (2), find price needed to keep the ORIGINAL CMR.\n5. Return to original data. Automation cuts V by 40% and doubles F. Compute CMR and BE units.\n6. Under automation: (a) minimum whole sales units for NOI $90,000; (b) contribution statement and DOL at 30,000 units; (c) advise whether to automate, explaining demand risk.", "zh": "篮球售价25，变动费用15（其中60%是直接人工），销量30,000，F210,000。原收入750,000、CM300,000、NOI90,000。\n1. 求CMR、保本销量、DOL。\n2. V增加3，售价不变，求新CMR和保本销量。\n3. 按第2问，要赚90,000至少卖多少整件？\n4. 按第2问，要维持原CMR需定价多少？\n5. 回到原数据：自动化使V下降40%、F翻倍，求CMR和保本量。\n6. 自动化下：（a）赚90,000最低整件销量（b）售30,000的贡献式报表和DOL（c）是否赞成自动化，说明需求风险。"}, "solution": {"en": "1. Unit CM 10; CMR 40%; BE 21,000; DOL 300,000/90,000 = 3.3333.\n2. V18, unit CM7, CMR28%, BE30,000.\n3. (210,000+90,000)/7 = 42,857.1429 → at least 42,858.\n4. (P−18)/P=.40 → P=18/.60=$30. Keeping dollar CM at $10 would be a different goal.\n5. V=15×.60=9; F420,000; unit CM16; CMR64%; theoretical BE26,250.\n6a. 510,000/16=31,875.\n6b. Sales750,000 − variable270,000 = CM480,000 − F420,000 = NOI60,000. DOL8.\n6c. At 30,000 units automation earns 30,000 less and exposes greater operating risk. Profit indifference with original technology: 16Q−420,000=10Q−210,000 → Q35,000. Above that, automation has higher modeled profit; below that, the original has higher profit. Investment timing, quality and demand uncertainty still matter.", "zh": "1. 单位CM10；CMR40%；保本21,000；DOL=300,000/90,000=3.3333。\n2. V18、单位CM7、CMR28%、保本30,000。\n3. 300,000/7=42,857.1429，至少42,858件。\n4. (P−18)/P=.40，因此P=30；维持原单位CM10不是同一要求。\n5. V=15×.60=9；F420,000；单位CM16、CMR64%、保本26,250。\n6a. 510,000/16=31,875。\n6b. 收入750,000−变动270,000=CM480,000−F420,000=NOI60,000；DOL8。\n6c. 30,000件时比原方案少赚30,000，经营风险更高。利润无差别点：16Q−420,000=10Q−210,000，Q35,000；超过此量自动化模型利润更高，低于则原方案更高。还需考虑投资时点、质量及需求不确定性。"}, "cards": ["l3-cm", "l3-be", "l3-dol", "l3-change"], "source": "Tutorial 2 Q1，PDF p.1（重述；未提供官方答案，本解答独立复算 / Independently derived）"}, {"id": "l3-e2", "title": {"en": "Contribution format and CM ratios", "zh": "贡献式报表与贡献毛益率"}, "prompt": {"en": "CM ratio 40%, sales increase $50,000 and fixed costs unchanged. Find increase in NOI.", "zh": "CM 率 40%，销售增加 50,000，固定成本不变，求 NOI 增量。"}, "solution": {"en": "20000 $\n50,000 × .40 = 20,000.", "zh": "20000 $\n50,000 × .40 = 20,000。"}, "cards": ["l3-cm"], "source": "原创基础题 / Original drill · 与模卡复测共享题目"}, {"id": "l3-e3", "title": {"en": "CVP assumptions and graphs", "zh": "CVP 假设与图形"}, "prompt": {"en": "P $30, V $18. Find slope of the profit line.", "zh": "P 30，V 18，求利润线斜率。"}, "solution": {"en": "12 $/unit\nSlope is unit CM = 30 − 18 = 12.", "zh": "12 $/unit\n斜率为单位 CM = 12。"}, "cards": ["l3-model"], "source": "原创基础题 / Original drill · 与模卡复测共享题目"}, {"id": "l3-e4", "title": {"en": "Incremental scenario analysis", "zh": "多因素变化的增量分析"}, "prompt": {"en": "Old P 500, V 300, Q 500. New P 480, Q 650, V 300; F rises 15,000. Find ΔNOI.", "zh": "旧 P 500、V 300、Q 500；新 P 480、Q 650、V 300；F 增加 15,000，求 ΔNOI。"}, "solution": {"en": "2000 $\n180 × 650 − 200 × 500 − 15,000 = 2,000.", "zh": "2000 $\n117,000 − 100,000 − 15,000 = 2,000。"}, "cards": ["l3-change"], "source": "原创基础题 / Original drill · 与模卡复测共享题目"}, {"id": "l3-e5", "title": {"en": "Special-order pricing", "zh": "特殊订单定价"}, "prompt": {"en": "Order 100 units, V $20, forgone contribution $500, target profit $300. Find price.", "zh": "订单 100 件，V 20，放弃贡献 500，目标利润 300，求报价。"}, "solution": {"en": "28 $/unit\n20 + (500 + 300)/100 = 28.", "zh": "28 $/unit\n20 + 8 = 28。"}, "cards": ["l3-order"], "source": "原创基础题 / Original drill · 与模卡复测共享题目"}, {"id": "l3-e6", "title": {"en": "Break-even and target profit", "zh": "保本与目标利润"}, "prompt": {"en": "F $210,000; unit CM $7; target $90,000. Minimum whole units?", "zh": "F 210,000，单位 CM 7，目标 90,000，至少多少整件？"}, "solution": {"en": "42858 units\n300,000/7 = 42,857.142…; round up to 42,858.", "zh": "42858 units\n300,000/7 后向上取整为 42,858。"}, "cards": ["l3-be"], "source": "原创基础题 / Original drill · 与模卡复测共享题目"}, {"id": "l3-e7", "title": {"en": "Margin of safety", "zh": "安全边际"}, "prompt": {"en": "MOS dollars $50,000 and CMR 40%. Find NOI.", "zh": "安全边际金额 50,000、CM 率 40%，求 NOI。"}, "solution": {"en": "20000 $\n50,000 × .40 = 20,000.", "zh": "20000 $\n50,000 × .40 = 20,000。"}, "cards": ["l3-mos"], "source": "原创基础题 / Original drill · 与模卡复测共享题目"}, {"id": "l3-e8", "title": {"en": "Cost structure and operating leverage", "zh": "成本结构与经营杠杆"}, "prompt": {"en": "MOS is 25% under the standard profitable CVP model. Find DOL.", "zh": "标准盈利 CVP 模型下 MOS 25%，求 DOL。"}, "solution": {"en": "4 times\n1/.25 = 4.", "zh": "4 times\n1/.25 = 4。"}, "cards": ["l3-dol"], "source": "原创基础题 / Original drill · 与模卡复测共享题目"}, {"id": "l3-e9", "title": {"en": "Sales mix, commissions and multiproduct BE", "zh": "销售组合、佣金与多产品保本"}, "prompt": {"en": "A/B revenue mix exactly 45%/55%; CMR 40%/55%; F $170,000. Find BE revenue.", "zh": "A/B 收入组合精确为 45%/55%，CMR 40%/55%，F 170,000，求保本收入。"}, "solution": {"en": "352331.61 $\nCMR = .45 × .4 + .55 × .55 = .4825; BE = 170,000/.4825 = 352,331.61.", "zh": "352331.61 $\nCMR = 48.25%；保本收入 352,331.61。"}, "cards": ["l3-mix"], "source": "原创基础题 / Original drill · 与模卡复测共享题目"}], "notes": [{"title": "保本数量向上取整", "body": "PDF p.65咖啡例1,300/1.13=1,150.442…；理论保本可列1,150.44，至少不亏的整杯数量为1,151，课件约数1,150会少0.50的CM。"}, {"title": "销售组合不能混用两套权重", "body": "PDF pp.100–105：250,000/550,000约45.4545%，并非精确45%。使用原始金额，总CMR=265,000/550,000，保本352,830.19。若题目明确45%/55%为精确权重，CMR48.25%，保本352,331.61。网站按题面明确的口径判分，避免把所有差异都叫舍入误差。"}]}, {"id": "l4", "title": {"en": "Variable costing & segments", "zh": "变动成本法与分部报告"}, "subtitle": "把存货的利润影响，与业务的盈利能力分开。", "sections": ["4-1 分部贡献式报告", "4-2 变动与吸收成本法", "4-3 管理含义与局限"], "cards": [{"id": "l4-segment", "section": 0, "title": {"en": "Segments and traceable vs common fixed costs", "zh": "分部与可追溯、共同固定成本"}, "pages": "7–12, 19–21", "body": ["分部是管理者希望取得收入、成本或利润信息的任何业务部分，如店铺、地区、产品线。组织可在股权集中时仍实行经营分权。", "可追溯固定成本因某分部存在而发生；共同固定成本支持多个分部，不能合理追溯给某一个。按楼面面积分摊并不会使共同成本变成可避免成本。", "分类依层级而变：电视事业部经理工资对事业部可追溯，但对其电视机与机顶盒产品线是共同成本。短期退出决策还应核实可避免时点，不能一概假定可追溯等于立即节省。"], "summary": "Traceability depends on the segment level. Common fixed costs remain unallocated in contribution-format segment reports.", "formula": "Company → Division → Product line", "trap": "同一成本在上层可追溯，在下层可共同。", "example": {"type": "choice", "prompt": {"en": "A division manager supervises two product lines. Salary is common to those lines.", "zh": "事业部经理管理两个产品线，其工资对这些产品线属于共同成本。"}, "options": [{"en": "True", "zh": "正确"}, {"en": "False", "zh": "错误"}], "answer": 0, "solution": {"en": "It is traceable to the division, not to one product line.", "zh": "可追溯到事业部，不能追溯到某一产品线。"}}, "concept": {"type": "choice", "prompt": {"en": "Allocating common cost to a segment makes it avoidable when the segment closes.", "zh": "将共同成本分给某分部，就能在关闭该分部时节省该成本。"}, "options": [{"en": "False", "zh": "错误"}, {"en": "True", "zh": "正确"}], "answer": 0, "solution": {"en": "Allocation changes reporting, not cost behavior.", "zh": "分配改变报表，不改变成本的可避免性。"}}, "applications": [{"type": "choice", "prompt": {"en": "A dedicated product manager’s salary is traceable to:", "zh": "专门产品经理工资可追溯到："}, "options": [{"en": "That product line", "zh": "该产品线"}, {"en": "Every unrelated product equally", "zh": "所有无关产品平均"}, {"en": "Customers by revenue automatically", "zh": "按收入自动追溯客户"}], "answer": 0, "solution": {"en": "The position exists because of that product line.", "zh": "职位因该产品线存在而发生。"}}, {"type": "choice", "prompt": {"en": "A segment can be a sales territory rather than a legal entity.", "zh": "分部可以是销售地区而非独立法人。"}, "options": [{"en": "True", "zh": "正确"}, {"en": "False", "zh": "错误"}], "answer": 0, "solution": {"en": "A segment is defined by managers’ information needs.", "zh": "分部由管理信息需要界定。"}}]}, {"id": "l4-margin", "section": 0, "title": {"en": "Segment margin and layered statements", "zh": "分部利润与分层利润表"}, "pages": "13–18, 21–22", "body": ["分部收入减去全部分部变动费用得到 CM；再减可追溯固定费用得到 Segment margin，用于评估长期分部盈利能力。公司 NOI = 各分部利润合计 − 公司共同固定费用。", "分层报告里，上层可追溯成本在下层可能成为共同费用，应在下层利润合计之后扣除。不要为了让每个产品承担所有费用而任意分配共同费用。", "CM 与 segment margin 用途不同：CM 体现覆盖固定费用的能力，segment margin 还扣除了维持分部的可追溯固定费用。"], "summary": "Segment margin equals contribution margin less traceable fixed costs; company common costs are deducted only at the company level.", "formula": "Segment margin = Sales − Variable expenses − Traceable F", "trap": "Segment margin 不是扣完任意分摊总部费用后的利润。", "example": {"type": "number", "prompt": {"en": "Segment sales $300,000, variable expenses $150,000, traceable F $90,000. Find segment margin.", "zh": "分部收入 300,000、变动费用 150,000、可追溯 F 90,000，求分部利润。"}, "answer": 60000, "solution": {"en": "300,000 − 150,000 − 90,000 = 60,000.", "zh": "150,000 − 90,000 = 60,000。"}, "unit": "$", "tolerance": 0.01}, "concept": {"type": "choice", "prompt": {"en": "Company NOI is obtained by subtracting common F from:", "zh": "公司 NOI 应由哪项减去共同 F 得到？"}, "options": [{"en": "Sum of segment margins", "zh": "分部利润之和"}, {"en": "Sales only", "zh": "仅收入"}, {"en": "Inventory", "zh": "存货"}], "answer": 0, "solution": {"en": "Segment margins already deduct variable and traceable fixed costs.", "zh": "分部利润已扣变动费用和可追溯固定费用。"}}, "applications": [{"type": "number", "prompt": {"en": "Margins $60,000 and $40,000; common F $25,000. Find company NOI.", "zh": "分部利润 60,000 和 40,000，共同 F 25,000，求公司 NOI。"}, "answer": 75000, "solution": {"en": "60,000 + 40,000 − 25,000 = 75,000.", "zh": "100,000 − 25,000 = 75,000。"}, "unit": "$", "tolerance": 0.01}, {"type": "number", "prompt": {"en": "Product margins $75,000 and −$5,000; division-common F $10,000. Find division margin.", "zh": "产品利润 75,000 和 −5,000，事业部共同 F 10,000，求事业部利润。"}, "answer": 60000, "solution": {"en": "75,000 − 5,000 − 10,000 = 60,000.", "zh": "70,000 − 10,000 = 60,000。"}, "unit": "$", "tolerance": 0.01}]}, {"id": "l4-drop", "section": 0, "title": {"en": "Keep-or-drop decisions", "zh": "保留或取消分部"}, "pages": "22–24, 32–38", "body": ["判断取消业务，应比较节省的可避免成本与失去的 CM，还要计入对其他业务的影响和新费用。分摊后亏损不代表应取消。", "酒吧例：CM 40,000、可避免固定成本 26,000，取消会使 NOI 降 14,000，即使被分摊共同费用 20,000 后显示亏损 6,000。", "机顶盒例还改变电视销量、CMR 和广告费用，不能只看 −5,000 分部利润。若可追溯固定成本短期不能避免，则要逐项调整。"], "summary": "Dropping a segment is beneficial only if avoidable costs and other gains exceed lost contribution and other losses.", "formula": "ΔNOI from dropping = Avoidable F − Lost CM + Other net effects", "trap": "已经分摊的共同成本不是自动可节省的成本。", "example": {"type": "number", "prompt": {"en": "Bar CM $40,000; avoidable F $26,000; common F stays. Find ΔNOI if dropped.", "zh": "酒吧 CM 40,000，可避免 F 26,000，共同 F 不变，取消后 ΔNOI？"}, "answer": -14000, "solution": {"en": "26,000 − 40,000 = −14,000.", "zh": "26,000 − 40,000 = −14,000，应保留。"}, "unit": "$", "tolerance": 0.01}, "concept": {"type": "choice", "prompt": {"en": "A loss after allocated common costs is sufficient evidence to close a segment.", "zh": "分摊共同费用后亏损，足以证明应关闭分部。"}, "options": [{"en": "False", "zh": "错误"}, {"en": "True", "zh": "正确"}], "answer": 0, "solution": {"en": "Use avoidable costs and lost contribution, not arbitrary allocations.", "zh": "应比较可避免成本与失去贡献，而非任意分摊。"}}, "applications": [{"type": "number", "prompt": {"en": "Dropping a line avoids $50,000 F, loses $45,000 CM, adds $1,400 other CM, and adds $6,000 ads. Find ΔNOI.", "zh": "取消产品线省 F 50,000，失 CM 45,000，其他 CM 增 1,400，广告增 6,000，求 ΔNOI。"}, "answer": 400, "solution": {"en": "50,000 − 45,000 + 1,400 − 6,000 = 400.", "zh": "5,000 + 1,400 − 6,000 = 400。"}, "unit": "$", "tolerance": 0.01}, {"type": "number", "prompt": {"en": "Lost CM $30,000; traceable F $40,000 but only $20,000 avoidable. Other effects zero. Find ΔNOI.", "zh": "失去 CM 30,000，可追溯 F 40,000 中仅 20,000 可避免，无其他影响，求 ΔNOI。"}, "answer": -10000, "solution": {"en": "20,000 − 30,000 = −10,000.", "zh": "仅可避免部分相关：20,000 − 30,000 = −10,000。"}, "unit": "$", "tolerance": 0.01}]}, {"id": "l4-be", "section": 0, "title": {"en": "Segment and company break-even", "zh": "分部与公司保本分析"}, "pages": "25–31, 39", "body": ["分部保本 = 本分部可追溯固定费用 / 本分部 CMR，不包含公司共同固定费用。公司保本则包含所有可追溯及共同固定费用，分母使用固定组合下公司整体 CMR。", "各分部恰好保本时，公司仍可能亏损共同固定费用；各分部保本额之和也不等于固定组合下公司保本额。", "报告应覆盖价值链上可归属成本，避免遗漏研发、设计、营销、配送或售后。课件还介绍外部分部披露的管理层视角及内部数据公开、合并调节等权衡；此处是课程口径，不作法规更新判断。"], "summary": "Segment BE excludes company common fixed costs; company BE includes all fixed costs and uses the overall CM ratio.", "formula": "Segment BE sales = Traceable F / Segment CMR", "trap": "不可用公司总体 CMR 替代一个分部自身 CMR。", "example": {"type": "number", "prompt": {"en": "Segment traceable F $90,000; CMR 50%. Find segment BE sales.", "zh": "分部可追溯 F 90,000，CMR 50%，求分部保本收入。"}, "answer": 180000, "solution": {"en": "90,000/.50 = 180,000.", "zh": "90,000/.50 = 180,000。"}, "unit": "$", "tolerance": 0.01}, "concept": {"type": "choice", "prompt": {"en": "If each segment covers only its own traceable F, the company:", "zh": "若各分部仅覆盖自身可追溯 F，公司："}, "options": [{"en": "May still lose common F", "zh": "可能仍亏损共同 F"}, {"en": "Must break even", "zh": "必定保本"}, {"en": "Has no common F", "zh": "没有共同 F"}], "answer": 0, "solution": {"en": "Company common costs still need coverage.", "zh": "公司共同成本仍需覆盖。"}}, "applications": [{"type": "number", "prompt": {"en": "Traceable F $170,000; common F $25,000; overall CMR 54%. Find company BE.", "zh": "可追溯 F 170,000、共同 F 25,000、整体 CMR 54%，求公司保本收入。"}, "answer": 361111.11, "solution": {"en": "195,000/.54 = 361,111.11.", "zh": "195,000/.54 = 361,111.11。"}, "unit": "$", "tolerance": 0.02}, {"type": "number", "prompt": {"en": "Segment sales $200,000; CM $120,000; traceable F $80,000. Find segment BE.", "zh": "分部收入 200,000、CM 120,000、可追溯 F 80,000，求分部保本收入。"}, "answer": 133333.33, "solution": {"en": "CMR = .60; 80,000/.60 = 133,333.33.", "zh": "CMR = .60；保本 133,333.33。"}, "unit": "$", "tolerance": 0.02}]}, {"id": "l4-unit", "section": 1, "title": {"en": "Product costs under VC and AC", "zh": "变动与吸收成本法的单位产品成本"}, "pages": "41–54", "body": ["吸收成本法 AC 将全部制造成本计入产品成本；变动成本法 VC 只将变动制造成本计入产品成本，固定制造费用 FMOH 当期费用化。两者都将销售管理费用作为期间费用。", "本课数值题把 DM、DL 视作变动；若题目另有固定直接人工等条件，需按成本行为解释，不能只背名称。", "Harvey：DM+DL 8、VMOH 2、FMOH 150,000、产量 25,000，因此 VC 单位成本 10、AC 16；变动 S&A 3 不进入任一存货单价。"], "summary": "The key distinction is fixed manufacturing overhead: product cost under AC, period expense under VC.", "formula": "VC unit cost = Variable manufacturing cost; AC unit cost = VC unit cost + FMOH / production", "trap": "V S&A 是变动费用，但不是产品存货成本。", "example": {"type": "number", "prompt": {"en": "Variable manufacturing cost $10; FMOH $150,000; production 25,000. AC unit cost?", "zh": "变动制造成本 10，FMOH 150,000，产量 25,000，AC 单位成本？"}, "answer": 16, "solution": {"en": "10 + 150,000/25,000 = 16.", "zh": "10 + 6 = 16。"}, "unit": "$/unit", "tolerance": 0.01}, "concept": {"type": "choice", "prompt": {"en": "Variable selling expense is a product cost under VC.", "zh": "变动销售费用在 VC 下是产品成本。"}, "options": [{"en": "False", "zh": "错误"}, {"en": "True", "zh": "正确"}], "answer": 0, "solution": {"en": "It is still a period expense, although deducted before CM.", "zh": "仍是期间费用，只是在 CM 前扣除。"}}, "applications": [{"type": "number", "prompt": {"en": "DM $5, DL $3, VMOH $2, V S&A $4. Find VC unit product cost.", "zh": "DM 5、DL 3、VMOH 2、变动 S&A 4，求 VC 单位产品成本。"}, "answer": 10, "solution": {"en": "5 + 3 + 2 = 10; exclude selling costs.", "zh": "5 + 3 + 2 = 10，不含销售费用。"}, "unit": "$/unit", "tolerance": 0.01}, {"type": "number", "prompt": {"en": "Variable manufacturing cost $2; FMOH $480,000; production 60,000. AC unit cost?", "zh": "变动制造成本 2，FMOH 480,000，产量 60,000，求 AC 单位成本。"}, "answer": 10, "solution": {"en": "2 + 480,000/60,000 = 10.", "zh": "2 + 8 = 10。"}, "unit": "$/unit", "tolerance": 0.01}]}, {"id": "l4-income", "section": 1, "title": {"en": "Preparing AC and VC statements", "zh": "编制两种成本法利润表"}, "pages": "55–64", "body": ["VC：销售 − 变动 COGS − 变动 S&A = CM，再减全部 FMOH 和固定 S&A = NOI。COGS 使用销量，不是产量；固定制造费用使用当期总额。", "AC：销售 − 吸收 COGS = 毛利，再减全部 S&A = NOI。未售产品中的 FMOH 留在存货，推迟到销售期间确认。", "Harvey 第一年产 25,000、售 20,000、P30、VC单价10、AC单价16、变动 S&A3、固定 S&A100,000，VC利润90,000、AC利润120,000。"], "summary": "VC uses contribution format; AC uses gross margin format. Inventory defers fixed manufacturing overhead only under AC.", "formula": "VC NOI = Qsold(P − Vmanufacturing − VS&A) − FMOH − FS&A", "trap": "不要在 AC 利润表既通过 COGS 扣 FMOH，又再把当期全部 FMOH 扣一次。", "example": {"type": "number", "prompt": {"en": "Harvey sells 20,000 at $30; variable manufacturing $10, variable S&A $3; FMOH $150,000 and FS&A $100,000. VC NOI?", "zh": "Harvey 售 20,000 件，P30，变动制造10，变动 S&A3，FMOH150,000、FS&A100,000，求 VC NOI。"}, "answer": 90000, "solution": {"en": "20,000 × (30 − 10 − 3) − 250,000 = 90,000.", "zh": "340,000 − 250,000 = 90,000。"}, "unit": "$", "tolerance": 0.01}, "concept": {"type": "choice", "prompt": {"en": "VC COGS normally uses:", "zh": "VC 销售成本通常用："}, "options": [{"en": "Units sold × applicable variable inventory cost", "zh": "销量 × 适用变动存货成本"}, {"en": "Units produced × selling price", "zh": "产量 × 售价"}, {"en": "All fixed cost", "zh": "全部固定费用"}], "answer": 0, "solution": {"en": "Unsold variable production cost remains in inventory.", "zh": "未售部分的变动制造成本仍留在存货。"}}, "applications": [{"type": "number", "prompt": {"en": "Sales $600,000; AC COGS $320,000; variable S&A $60,000; fixed S&A $100,000. AC NOI?", "zh": "收入600,000；AC COGS320,000；变动S&A60,000；固定S&A100,000，求AC NOI。"}, "answer": 120000, "solution": {"en": "600,000 − 320,000 − 60,000 − 100,000 = 120,000.", "zh": "毛利280,000减S&A160,000 = 120,000。"}, "unit": "$", "tolerance": 0.01}, {"type": "number", "prompt": {"en": "Sales 30,000 units at $30; all variable expense $13/unit; total fixed $250,000. VC NOI?", "zh": "售30,000件、P30；全部变动费用13/件；总固定250,000，求VC NOI。"}, "answer": 260000, "solution": {"en": "30,000 × 17 − 250,000 = 260,000.", "zh": "510,000 − 250,000 = 260,000。"}, "unit": "$", "tolerance": 0.01}]}, {"id": "l4-reconcile", "section": 1, "title": {"en": "Profit reconciliation and inventory layers", "zh": "利润调节与跨期存货层"}, "pages": "60–70; Tutorial 2 Q2", "body": ["最通用的调节式：AC NOI − VC NOI = 期末存货中的 FMOH − 期初存货中的 FMOH（在本课无其他差异的设定下）。存货增加通常使 AC 利润较高，减少则相反。", "仅在各存货层固定制造费用率相同时，才可简化为存货件数变化 × 单位 FMOH。年度产量变化导致率变化时，必须按 FIFO 或题目指定成本流假设跟踪历史层。", "Starfax 第三年：期初 20,000 件含前期 FMOH 8/件，期末 10,000 件含当期 12/件；差额 120,000 − 160,000 = −40,000，不能只用 −10,000 × 12。"], "summary": "Reconcile using fixed overhead in ending inventory minus fixed overhead in beginning inventory, respecting historical layers.", "formula": "AC NOI = VC NOI + Ending inventory FMOH − Beginning inventory FMOH", "trap": "率变化时，“产量减销量 × 当期率”通常会错。", "example": {"type": "number", "prompt": {"en": "VC NOI $90,000; beginning inventory zero; end 5,000 units carrying $6 FMOH each. AC NOI?", "zh": "VC NOI90,000；期初无存货；期末5,000件、FMOH6/件，求AC NOI。"}, "answer": 120000, "solution": {"en": "90,000 + 5,000 × 6 = 120,000.", "zh": "90,000 + 30,000 = 120,000。"}, "unit": "$", "tolerance": 0.01}, "concept": {"type": "choice", "prompt": {"en": "If historical FMOH rates differ, reconciliation must use:", "zh": "历史 FMOH 率不同时，调节应使用："}, "options": [{"en": "Fixed overhead amounts in actual inventory layers", "zh": "实际存货层内的固定费用金额"}, {"en": "Only current rate times unit change", "zh": "只用当前率乘数量变化"}, {"en": "Selling price times inventory", "zh": "售价乘存货"}], "answer": 0, "solution": {"en": "Beginning and ending inventory may carry different rates.", "zh": "期初与期末存货可能携带不同成本率。"}}, "applications": [{"type": "number", "prompt": {"en": "VC NOI $30,000; beginning 20,000 units at FMOH $8; ending 10,000 at FMOH $12. Find AC NOI.", "zh": "VC NOI30,000；期初20,000件含FMOH8；期末10,000件含FMOH12，求AC NOI。"}, "answer": -10000, "solution": {"en": "30,000 + 120,000 − 160,000 = −10,000.", "zh": "30,000 + 120,000 − 160,000 = −10,000。"}, "unit": "$", "tolerance": 0.01}, {"type": "number", "prompt": {"en": "AC NOI $60,000; ending inventory FMOH $160,000; beginning zero. Find VC NOI.", "zh": "AC NOI60,000；期末存货FMOH160,000；期初零，求VC NOI。"}, "answer": -100000, "solution": {"en": "VC = 60,000 − 160,000 = −100,000.", "zh": "VC = AC − 递延FMOH = −100,000。"}, "unit": "$", "tolerance": 0.01}]}, {"id": "l4-meaning", "section": 2, "title": {"en": "Overproduction, CVP and capacity limits", "zh": "过量生产、CVP 与产能边界"}, "pages": "71–81", "body": ["AC 下多生产而未售出的产品可以递延 FMOH，从而在销量不增时提高当期账面利润。这不等于现金或经济价值增加，还可能造成仓储、过时风险。", "VC 将 FMOH 当期费用化，在价格、单位变动成本、总固定费用稳定时，NOI 随销量而非产量变化，适合 CVP 和短期经营分析。AC 对外报告和长期覆盖全部制造成本有价值。", "两种方法的简单模型都把产能视为既定。按用量购买云服务较接近变动费用；自建基础设施有阶梯固定成本和多期需求风险，需超出单期 CVP 框架分析。"], "summary": "Absorption profit can rise through inventory buildup. Variable costing better isolates sales-driven performance within a fixed-capacity model.", "formula": "More production ≠ More sales ≠ More cash", "trap": "VC 也不能让长期产能承诺和固定费用消失。", "example": {"type": "number", "prompt": {"en": "Same sales; ending inventory grows by 1,000 units at a stable FMOH rate $6. Extra AC profit versus VC?", "zh": "销量相同；存货增加1,000件，稳定FMOH率6，AC相对VC多多少利润？"}, "answer": 6000, "solution": {"en": "1,000 × 6 = 6,000 deferred fixed overhead.", "zh": "递延固定费用 = 6,000。"}, "unit": "$", "tolerance": 0.01}, "concept": {"type": "choice", "prompt": {"en": "Higher AC profit caused only by inventory buildup proves better economic performance.", "zh": "仅因存货增加导致AC利润提高，能证明经济表现改善。"}, "options": [{"en": "False", "zh": "错误"}, {"en": "True", "zh": "正确"}], "answer": 0, "solution": {"en": "It may only be a timing shift in expense recognition.", "zh": "可能仅是费用确认时点转移。"}}, "applications": [{"type": "number", "prompt": {"en": "Sell 14,000 at $30, variable expense $13/unit; F $250,000. VC profit?", "zh": "售14,000件、P30、全部变动费用13/件、F250,000，求VC利润。"}, "answer": -12000, "solution": {"en": "14,000 × 17 − 250,000 = −12,000.", "zh": "238,000 − 250,000 = −12,000。"}, "unit": "$", "tolerance": 0.01}, {"type": "choice", "prompt": {"en": "Building a new data center with step-fixed costs is well captured by an unchanged one-period linear CVP model.", "zh": "新建数据中心的阶梯固定成本可由不变的单期线性CVP模型充分描述。"}, "options": [{"en": "False", "zh": "错误"}, {"en": "True", "zh": "正确"}], "answer": 0, "solution": {"en": "Capacity steps and multi-period commitments require an expanded analysis.", "zh": "产能台阶与多期承诺需要扩展分析。"}}]}], "exercises": [{"id": "l4-e1", "title": {"en": "Starfax: three-year reconciliation", "zh": "Starfax：三年利润调节"}, "prompt": {"en": "Years 1/2/3: production 50,000/60,000/40,000; sales units 50,000/40,000/50,000; revenue $800,000/$640,000/$800,000. Variable manufacturing $2/unit; FMOH $480,000 annually; V S&A $1 per unit sold; fixed S&A $140,000 annually. Beginning inventory in year 1 is zero. Use FIFO and recompute FMOH rate each year using actual production.\nReported AC NOI: $30,000/$60,000/−$10,000; AC COGS $580,000/$400,000/$620,000.\n1. Prepare VC statements for all years.\n2. Compute AC unit costs, showing variable and fixed portions.\n3. Reconcile each year and explain why year 2 income increased while sales fell.", "zh": "第1/2/3年产量50,000/60,000/40,000；销量50,000/40,000/50,000；收入800,000/640,000/800,000。单位变动制造2；每年FMOH480,000；单位变动S&A1；每年固定S&A140,000。第一年期初零存货。FIFO，每年按实际产量重新算固定制造率。\n已报告AC NOI30,000/60,000/−10,000；AC COGS580,000/400,000/620,000。\n1. 编三年VC利润表。2. 算三年AC单价及变动/固定构成。3. 逐年调节并解释第二年销售下降但利润上升。"}, "solution": {"en": "1. Columns Y1 / Y2 / Y3:\nSales 800,000 / 640,000 / 800,000.\nVariable COGS 100,000 / 80,000 / 100,000.\nVariable S&A 50,000 / 40,000 / 50,000.\nCM 650,000 / 520,000 / 650,000.\nFMOH 480,000 each; fixed S&A 140,000 each.\nVC NOI 30,000 / −100,000 / 30,000.\n2. FMOH/unit 9.60 / 8.00 / 12.00; add variable $2 → AC unit costs 11.60 / 10.00 / 14.00.\n3. Y1 no inventory change, difference zero. Y2 ending 20,000 units×$8 = $160,000 deferred: −100,000+160,000=60,000. Y3 beginning FMOH160,000, ending10,000×$12=120,000: 30,000+120,000−160,000=−10,000. FIFO Y3 COGS=20,000×10+30,000×14=620,000.\nY2 inventory buildup masks the sales-driven loss. Three-year VC total−40,000 versus AC80,000 differs by remaining inventory FMOH120,000.", "zh": "1. 按第1/2/3年列示：收入800,000/640,000/800,000；变动COGS100,000/80,000/100,000；变动S&A50,000/40,000/50,000；CM650,000/520,000/650,000；每年FMOH480,000、固定S&A140,000；VC NOI30,000/−100,000/30,000。\n2. 固定制造率9.60/8.00/12.00；加变动制造2，AC单位成本11.60/10.00/14.00。\n3. 第一年存货零，差额零。第二年期末20,000件×8=160,000递延：−100,000+160,000=60,000。第三年期初FMOH160,000、期末10,000×12=120,000，AC=30,000+120,000−160,000=−10,000。FIFO第三年COGS=20,000×10+30,000×14=620,000。\n第二年库存积压掩盖销售下滑带来的亏损。三年VC合计−40,000、AC80,000，相差期末仍留存的FMOH120,000。"}, "cards": ["l4-unit", "l4-income", "l4-reconcile", "l4-meaning"], "source": "Tutorial 2 Q2，PDF p.2（重述；独立复算 / Independently derived）"}, {"id": "l4-e2", "title": {"en": "Vulcan: two levels of segment reporting", "zh": "Vulcan：两层分部报告"}, "prompt": {"en": "Company sales $750,000, variable expense $336,000, fixed expense $378,000. North sales $300,000, variable $156,000, traceable fixed $120,000. South has the remaining sales/variable costs and traceable fixed $108,000. Remaining F is company-common.\nNorth sells Paks $50,000 and Tibs $250,000. Variable expense ratios are 22% and 58%; traceable F $30,000 and $40,000; remaining North F is common to products.\nPrepare (1) company report by territory and (2) North report by product. Express each column’s costs and margins as a percentage of its own sales, rounded to one decimal.", "zh": "公司收入750,000、变动费用336,000、固定费用378,000。北部收入300,000、变动156,000、可追溯固定120,000；南部承担剩余收入和变动费用，可追溯固定108,000；其余为公司共同固定。\n北部Paks收入50,000、Tibs250,000；变动费用率分别22%、58%；产品可追溯F30,000、40,000；剩余北部F为产品共同费用。\n编（1）按地区分部报告（2）北部按产品分部报告。各列费用、利润除以该列收入，百分比保留一位。"}, "solution": {"en": "1. Total / North / South ($): sales750,000/300,000/450,000; variable336,000/156,000/180,000; CM414,000/144,000/270,000; traceable F228,000/120,000/108,000; territory margins186,000/24,000/162,000. Company-common F150,000; company NOI36,000.\nPercent of own-column sales: variable44.8%/52.0%/40.0%; CM55.2%/48.0%/60.0%; traceable F30.4%/40.0%/24.0%; margin24.8%/8.0%/36.0%. Company-common20.0%; NOI4.8%.\n2. North / Paks / Tibs: sales300,000/50,000/250,000; variable156,000/11,000/145,000; CM144,000/39,000/105,000; product-traceable F70,000/30,000/40,000; product margins74,000/9,000/65,000. North-common50,000; North margin24,000.\nPercent: variable52.0%/22.0%/58.0%; CM48.0%/78.0%/42.0%; traceable F23.3%/60.0%/16.0%; product margins24.7%/18.0%/26.0%. North-common16.7%; final margin8.0%. The $50,000 is traceable at territory level but common at product level.", "zh": "1. 总公司/北部/南部：收入750,000/300,000/450,000；变动336,000/156,000/180,000；CM414,000/144,000/270,000；可追溯F228,000/120,000/108,000；地区利润186,000/24,000/162,000。公司共同F150,000；NOI36,000。\n各列占自身收入比：变动44.8%/52.0%/40.0%；CM55.2%/48.0%/60.0%；可追溯F30.4%/40.0%/24.0%；地区利润24.8%/8.0%/36.0%。公司共同20.0%，NOI4.8%。\n2. 北部/Paks/Tibs：收入300,000/50,000/250,000；变动156,000/11,000/145,000；CM144,000/39,000/105,000；产品可追溯F70,000/30,000/40,000；产品利润74,000/9,000/65,000。北部共同50,000；北部利润24,000。\n百分比：变动52.0%/22.0%/58.0%；CM48.0%/78.0%/42.0%；可追溯F23.3%/60.0%/16.0%；产品利润24.7%/18.0%/26.0%。北部共同16.7%，最终利润8.0%。50,000在地区层面可追溯，在产品层面共同。"}, "cards": ["l4-segment", "l4-margin", "l4-be"], "source": "Tutorial 2 Q3，PDF p.3（重述；独立复算 / Independently derived）"}, {"id": "l4-e3", "title": {"en": "Segments and traceable vs common fixed costs", "zh": "分部与可追溯、共同固定成本"}, "prompt": {"en": "A segment can be a sales territory rather than a legal entity.\n1. True\n2. False", "zh": "分部可以是销售地区而非独立法人。\n1. 正确\n2. 错误"}, "solution": {"en": "True\nA segment is defined by managers’ information needs.", "zh": "正确\n分部由管理信息需要界定。"}, "cards": ["l4-segment"], "source": "原创基础题 / Original drill · 与模卡复测共享题目"}, {"id": "l4-e4", "title": {"en": "Segment margin and layered statements", "zh": "分部利润与分层利润表"}, "prompt": {"en": "Product margins $75,000 and −$5,000; division-common F $10,000. Find division margin.", "zh": "产品利润 75,000 和 −5,000，事业部共同 F 10,000，求事业部利润。"}, "solution": {"en": "60000 $\n75,000 − 5,000 − 10,000 = 60,000.", "zh": "60000 $\n70,000 − 10,000 = 60,000。"}, "cards": ["l4-margin"], "source": "原创基础题 / Original drill · 与模卡复测共享题目"}, {"id": "l4-e5", "title": {"en": "Keep-or-drop decisions", "zh": "保留或取消分部"}, "prompt": {"en": "Lost CM $30,000; traceable F $40,000 but only $20,000 avoidable. Other effects zero. Find ΔNOI.", "zh": "失去 CM 30,000，可追溯 F 40,000 中仅 20,000 可避免，无其他影响，求 ΔNOI。"}, "solution": {"en": "-10000 $\n20,000 − 30,000 = −10,000.", "zh": "-10000 $\n仅可避免部分相关：20,000 − 30,000 = −10,000。"}, "cards": ["l4-drop"], "source": "原创基础题 / Original drill · 与模卡复测共享题目"}, {"id": "l4-e6", "title": {"en": "Segment and company break-even", "zh": "分部与公司保本分析"}, "prompt": {"en": "Segment sales $200,000; CM $120,000; traceable F $80,000. Find segment BE.", "zh": "分部收入 200,000、CM 120,000、可追溯 F 80,000，求分部保本收入。"}, "solution": {"en": "133333.33 $\nCMR = .60; 80,000/.60 = 133,333.33.", "zh": "133333.33 $\nCMR = .60；保本 133,333.33。"}, "cards": ["l4-be"], "source": "原创基础题 / Original drill · 与模卡复测共享题目"}, {"id": "l4-e7", "title": {"en": "Product costs under VC and AC", "zh": "变动与吸收成本法的单位产品成本"}, "prompt": {"en": "Variable manufacturing cost $2; FMOH $480,000; production 60,000. AC unit cost?", "zh": "变动制造成本 2，FMOH 480,000，产量 60,000，求 AC 单位成本。"}, "solution": {"en": "10 $/unit\n2 + 480,000/60,000 = 10.", "zh": "10 $/unit\n2 + 8 = 10。"}, "cards": ["l4-unit"], "source": "原创基础题 / Original drill · 与模卡复测共享题目"}, {"id": "l4-e8", "title": {"en": "Preparing AC and VC statements", "zh": "编制两种成本法利润表"}, "prompt": {"en": "Sales 30,000 units at $30; all variable expense $13/unit; total fixed $250,000. VC NOI?", "zh": "售30,000件、P30；全部变动费用13/件；总固定250,000，求VC NOI。"}, "solution": {"en": "260000 $\n30,000 × 17 − 250,000 = 260,000.", "zh": "260000 $\n510,000 − 250,000 = 260,000。"}, "cards": ["l4-income"], "source": "原创基础题 / Original drill · 与模卡复测共享题目"}, {"id": "l4-e9", "title": {"en": "Profit reconciliation and inventory layers", "zh": "利润调节与跨期存货层"}, "prompt": {"en": "AC NOI $60,000; ending inventory FMOH $160,000; beginning zero. Find VC NOI.", "zh": "AC NOI60,000；期末存货FMOH160,000；期初零，求VC NOI。"}, "solution": {"en": "-100000 $\nVC = 60,000 − 160,000 = −100,000.", "zh": "-100000 $\nVC = AC − 递延FMOH = −100,000。"}, "cards": ["l4-reconcile"], "source": "原创基础题 / Original drill · 与模卡复测共享题目"}, {"id": "l4-e10", "title": {"en": "Overproduction, CVP and capacity limits", "zh": "过量生产、CVP 与产能边界"}, "prompt": {"en": "Building a new data center with step-fixed costs is well captured by an unchanged one-period linear CVP model.\n1. False\n2. True", "zh": "新建数据中心的阶梯固定成本可由不变的单期线性CVP模型充分描述。\n1. 错误\n2. 正确"}, "solution": {"en": "False\nCapacity steps and multi-period commitments require an expanded analysis.", "zh": "错误\n产能台阶与多期承诺需要扩展分析。"}, "cards": ["l4-meaning"], "source": "原创基础题 / Original drill · 与模卡复测共享题目"}], "notes": [{"title": "课件里的“单位变动制造费用”不是全部单位产品成本", "body": "PDF pp.57–59的40,000/10,000只追踪每件2元的变动制造费用，不包括每件8元DM+DL。完整VC COGS为200,000，期末存货50,000；完整AC COGS320,000，期末存货80,000。"}, {"title": "不同年度成本率需保留存货层", "body": "Tutorial 2 Starfax的FMOH率为9.60、8、12。第三年AC−VC为120,000−160,000=−40,000，不能用净库存下降10,000×当前率12替代。"}]}, {"id": "l5", "title": {"en": "Activity-based costing", "zh": "作业成本法"}, "subtitle": "从“平均分摊”走向资源消耗的因果关系。", "sections": ["5-1 ABC 原理与活动层级", "5-2 五步实施与利润报告", "5-3 改进、局限与时间驱动 ABC"], "cards": [{"id": "l5-overview", "section": 0, "title": {"en": "ABC vs traditional costing", "zh": "ABC 与传统成本法"}, "pages": "3–13, 61–64", "body": ["传统大平均分摊在产品同质、间接费用低时较简单；产品复杂度不同、批次和设计需求差异大时，单一产量基础可能扭曲成本，常见结果是高量简单产品被多计、低量复杂产品被少计。", "本课 ABC 的三项差异：按因果关系纳入部分非制造费用；不把组织维持和闲置产能成本分到产品；使用多个活动成本池及不同驱动因素。", "ABC 用于内部产品/客户盈利分析，其“产品成本”口径不等同外部存货计价。ABC 和官方吸收系统通常并存。"], "summary": "ABC uses causal activities, may include attributable nonmanufacturing costs, and excludes organization-sustaining and unused-capacity costs from product assignments.", "formula": "Resources → Activities → Cost objects", "trap": "不是“池越多越好”，也不是把所有费用硬分给产品。", "example": {"type": "choice", "prompt": {"en": "Shipping traceable to a product may enter its ABC product margin calculation.", "zh": "可追溯到产品的运输费用可以进入ABC产品利润计算。"}, "options": [{"en": "True", "zh": "正确"}, {"en": "False", "zh": "错误"}], "answer": 0, "solution": {"en": "ABC includes attributable nonmanufacturing costs for internal analysis.", "zh": "内部ABC可纳入可归属的非制造费用。"}}, "concept": {"type": "choice", "prompt": {"en": "Which is excluded from product assignments in the lecture’s ABC model?", "zh": "本课ABC不分给产品的是："}, "options": [{"en": "Unused-capacity costs", "zh": "闲置产能成本"}, {"en": "Traceable shipping", "zh": "可追溯运输"}, {"en": "Product design activity", "zh": "产品设计作业"}], "answer": 0, "solution": {"en": "Unused capacity is shown separately.", "zh": "闲置产能单独列示。"}}, "applications": [{"type": "choice", "prompt": {"en": "Single volume-based allocation may undercost:", "zh": "单一产量基础可能少计哪种产品成本？"}, "options": [{"en": "Low-volume complex products", "zh": "低量复杂产品"}, {"en": "All products equally", "zh": "所有产品等量"}, {"en": "Only direct materials", "zh": "仅直接材料"}], "answer": 0, "solution": {"en": "Complex products consume disproportionate batch/design resources.", "zh": "复杂产品可能消耗不成比例的批次、设计资源。"}}, {"type": "choice", "prompt": {"en": "ABC product cost automatically equals external inventory cost.", "zh": "ABC产品成本自动等于外部存货成本。"}, "options": [{"en": "False", "zh": "错误"}, {"en": "True", "zh": "正确"}], "answer": 0, "solution": {"en": "The cost scope and exclusions can differ.", "zh": "成本范围和排除项目可能不同。"}}]}, {"id": "l5-levels", "section": 0, "title": {"en": "Activities, pools and five levels", "zh": "活动、成本池与五种层级"}, "pages": "12–18, 22–23", "body": ["活动是导致资源消耗的事件；成本池汇集由同一活动指标解释的成本；活动指标也称驱动因素。交易驱动因素数次数，持续时间驱动因素数小时/分钟，后者适合每次耗时差异大。", "单位层级随每件发生，如机器加工；批次层级随每批发生，如设置、订单处理；产品层级维持特定产品，如设计和专利；客户层级维持客户关系；组织维持层级支持整个组织。", "只有单位层级天然随产量。客户层级归客户，不应无因果依据分给产品；组织维持成本在本模型不分给产品或客户。"], "summary": "The five levels distinguish unit, batch, product, customer and organization-sustaining demands.", "formula": "Transaction driver = count; Duration driver = time", "trap": "一个订单可能含很多件，不能把每订单成本直接当每件成本。", "example": {"type": "choice", "prompt": {"en": "Setup once for a batch of 500 units is:", "zh": "500件一批设置一次，设置属于："}, "options": [{"en": "Batch-level", "zh": "批次层级"}, {"en": "Unit-level", "zh": "单位层级"}, {"en": "Customer-level necessarily", "zh": "必然客户层级"}], "answer": 0, "solution": {"en": "The setup occurs per batch, not per unit.", "zh": "每批发生一次，不随批内件数逐件发生。"}}, "concept": {"type": "choice", "prompt": {"en": "Annual gifts for a customer are generally:", "zh": "每年给某客户的礼品通常属于："}, "options": [{"en": "Customer-level", "zh": "客户层级"}, {"en": "Unit-level", "zh": "单位层级"}, {"en": "Direct material", "zh": "直接材料"}], "answer": 0, "solution": {"en": "They support the relationship, not a specific unit.", "zh": "支持客户关系，不针对某一件产品。"}}, "applications": [{"type": "choice", "prompt": {"en": "If orders vary greatly in service time, which driver may improve precision?", "zh": "订单处理时间差异大，哪种驱动因素可能更精确？"}, "options": [{"en": "Service minutes", "zh": "服务分钟数"}, {"en": "Order count alone", "zh": "仅订单数"}, {"en": "Product sales price", "zh": "产品售价"}], "answer": 0, "solution": {"en": "Duration captures unequal resource use per transaction.", "zh": "时间能反映每次交易资源使用差异。"}}, {"type": "choice", "prompt": {"en": "Maintaining a patent for one product is:", "zh": "维持某产品专利属于："}, "options": [{"en": "Product-level", "zh": "产品层级"}, {"en": "Batch-level", "zh": "批次层级"}, {"en": "Unit-level", "zh": "单位层级"}], "answer": 0, "solution": {"en": "The activity supports the product irrespective of units or batches.", "zh": "支持产品存在，不取决于件数或批数。"}}]}, {"id": "l5-first", "section": 1, "title": {"en": "Five steps and first-stage allocation", "zh": "实施五步与第一阶段分配"}, "pages": "19–32", "body": ["五步：定义活动与池及指标；将间接资源成本分到池；计算活动率；按成本对象使用量二次分配；编管理报告。能直接追溯的 DM、DL、运输费先直接追溯，不能再放进池重复分配。", "第一阶段把按职能归集的资源费用转成活动成本，例如间接工资6,000,000，其中30%支持订单，订单池分得1,800,000。比例可来自访谈或使用记录，每项资源分配比例应合计100%。", "Baxter 的池合计22,000,000，包括客户关系3,080,000与Other6,160,000；Other不再分给产品。组合池应保持成本驱动同质性。"], "summary": "First-stage allocation assigns resource costs to activity pools; second-stage allocation assigns activity costs to cost objects.", "formula": "Pool cost = Σ(Resource cost × Share used by activity)", "trap": "第一阶段的分配比例不是第二阶段的产品活动量。", "example": {"type": "number", "prompt": {"en": "Indirect wages $6,000,000; 30% used for orders. Order pool allocation?", "zh": "间接工资6,000,000，订单占30%，订单池分配额？"}, "answer": 1800000, "solution": {"en": "6,000,000 × .30 = 1,800,000.", "zh": "6,000,000 × .30 = 1,800,000。"}, "unit": "$", "tolerance": 0.01}, "concept": {"type": "choice", "prompt": {"en": "First-stage allocation assigns:", "zh": "第一阶段分配的是："}, "options": [{"en": "Resources to activity pools", "zh": "资源成本到活动池"}, {"en": "Products to customers", "zh": "产品到客户"}, {"en": "Profit to employees", "zh": "利润到员工"}], "answer": 0, "solution": {"en": "Resources are reorganized by activity.", "zh": "按活动重新归集资源成本。"}}, "applications": [{"type": "number", "prompt": {"en": "Resource cost $900,000; 30% orders and 20% customer relations. How much remains for other activities?", "zh": "资源成本900,000，订单30%、客户关系20%，剩余其他活动多少？"}, "answer": 450000, "solution": {"en": "900,000 × (1 − .30 − .20) = 450,000.", "zh": "900,000 × .50 = 450,000。"}, "unit": "$", "tolerance": 0.01}, {"type": "number", "prompt": {"en": "Total indirect resources $22m; product pools $12.76m; customer pool $3.08m. Other pool in dollars?", "zh": "间接资源22百万，产品池12.76百万、客户池3.08百万，Other池多少美元？"}, "answer": 6160000, "solution": {"en": "22,000,000 − 12,760,000 − 3,080,000 = 6,160,000.", "zh": "22,000,000 − 12,760,000 − 3,080,000 = 6,160,000。"}, "unit": "$", "tolerance": 0.01}]}, {"id": "l5-rate", "section": 1, "title": {"en": "Activity rates and second-stage allocation", "zh": "活动率与第二阶段分配"}, "pages": "33–43", "body": ["活动率 = 池成本 / 总活动量，单位必须写清，如每订单、每设计变更、每机器小时。第二阶段：每项活动率 × 某产品或客户活动使用量，再相加。", "Baxter：订单452/单、设计760/次、机器6.50/小时、客户关系1,540/客户。产品不承担客户关系池，但客户报告可以承担。", "机器时间分钟转小时：36分钟 = 0.6小时。对账时已分配给产品 + 未分给产品 = 总池成本；未分配不等于没有成本。"], "summary": "Apply each pool’s own rate to the object’s usage of that same activity.", "formula": "Assigned ABC overhead = Σ(Activity rate × Object activity usage)", "trap": "不要用订单数量乘机器小时率，或把客户关系重复分给每个产品。", "example": {"type": "number", "prompt": {"en": "Order pool $4,520,000 and 10,000 orders. Cost per order?", "zh": "订单池4,520,000，10,000单，求每单成本。"}, "answer": 452, "solution": {"en": "4,520,000/10,000 = 452.", "zh": "4,520,000/10,000 = 452。"}, "unit": "$/order", "tolerance": 0.01}, "concept": {"type": "choice", "prompt": {"en": "Second-stage allocation uses:", "zh": "第二阶段使用："}, "options": [{"en": "Cost object activity consumption", "zh": "成本对象的活动耗用"}, {"en": "Total sales regardless of driver", "zh": "不论驱动因素用总收入"}, {"en": "Only direct material price", "zh": "仅材料单价"}], "answer": 0, "solution": {"en": "Activities trace the use of indirect resources.", "zh": "通过活动耗用追踪间接资源。"}}, "applications": [{"type": "number", "prompt": {"en": "SureStart: 4,000 orders at $452 and 480,000 MH at $6.50; no designs. Assigned overhead?", "zh": "SureStart：4,000单×452，480,000MH×6.50，无设计变更，求分配额。"}, "answer": 4928000, "solution": {"en": "4,000 × 452 + 480,000 × 6.5 = 4,928,000.", "zh": "1,808,000 + 3,120,000 = 4,928,000。"}, "unit": "$", "tolerance": 0.01}, {"type": "number", "prompt": {"en": "Customer: 12 orders at $452, 4 designs at $760, 448 MH at $6.50, customer cost $1,540. Assigned overhead?", "zh": "客户12单×452、4设计×760、448MH×6.50、客户成本1,540，求分配额。"}, "answer": 12916, "solution": {"en": "5,424 + 3,040 + 2,912 + 1,540 = 12,916.", "zh": "5,424 + 3,040 + 2,912 + 1,540 = 12,916。"}, "unit": "$", "tolerance": 0.01}]}, {"id": "l5-margin", "section": 1, "title": {"en": "Product and customer profitability", "zh": "产品与客户盈利分析"}, "pages": "44–64", "body": ["ABC 产品利润 = 产品收入 − 直接成本 − 产品消耗的活动成本。客户利润还要减该客户的客户层级成本。不要将产品报告与客户报告简单相加，因为它们是同一成本的不同分析视角。", "Baxter 产品利润合计7.24m，减客户关系3.08m及Other6.16m，得到总亏损2m，与传统报告勾稽。ABC改变归属与决策信息，不凭空改变总公司利润。", "判断低利润客户还需考虑未来增长、忠诚度、进入壁垒与生命周期价值；分配固定费用不一定可在停止服务时立刻避免。"], "summary": "ABC reveals who consumes resources; reconcile object margins to total income and distinguish assigned cost from avoidable cost.", "formula": "Customer margin = Customer revenue − Direct costs − Assigned activity costs", "trap": "ABC分配成本不自动等于短期可避免成本。", "example": {"type": "number", "prompt": {"en": "Customer sales $29,200; direct costs $15,900; assigned ABC $12,916. Customer margin?", "zh": "客户收入29,200，直接成本15,900，ABC分配12,916，求客户利润。"}, "answer": 384, "solution": {"en": "29,200 − 15,900 − 12,916 = 384.", "zh": "29,200 − 28,816 = 384。"}, "unit": "$", "tolerance": 0.01}, "concept": {"type": "choice", "prompt": {"en": "ABC and traditional reports must reconcile to the same total income when all costs are accounted for.", "zh": "若所有成本均核对，ABC与传统报告应勾稽到同一公司总利润。"}, "options": [{"en": "True", "zh": "正确"}, {"en": "False", "zh": "错误"}], "answer": 0, "solution": {"en": "Cost attribution changes, but total resource cost does not.", "zh": "成本归属改变，总资源成本不变。"}}, "applications": [{"type": "number", "prompt": {"en": "Product margins total $7,240,000; customer cost $3,080,000; Other $6,160,000. Company NOI?", "zh": "产品利润合计7,240,000，客户成本3,080,000，Other6,160,000，求公司NOI。"}, "answer": -2000000, "solution": {"en": "7,240,000 − 3,080,000 − 6,160,000 = −2,000,000.", "zh": "7,240,000 − 9,240,000 = −2,000,000。"}, "unit": "$", "tolerance": 0.01}, {"type": "number", "prompt": {"en": "LongLife revenue $18.7m, DM $6m, DL $5m, shipping $1m, ABC overhead $7.832m. Product margin in dollars?", "zh": "LongLife收入18.7百万，DM6百万、DL5百万、运输1百万、ABC7.832百万，求产品利润美元。"}, "answer": -1132000, "solution": {"en": "18,700,000 − 6,000,000 − 5,000,000 − 1,000,000 − 7,832,000 = −1,132,000.", "zh": "18,700,000 − 19,832,000 = −1,132,000。"}, "unit": "$", "tolerance": 0.01}]}, {"id": "l5-abm", "section": 2, "title": {"en": "ABM, benchmarking and limitations", "zh": "作业管理、标杆与局限"}, "pages": "65–72, 79–80", "body": ["ABM 用活动信息识别浪费、减少加工时间和缺陷；benchmarking 对比活动成本和流程，寻找改善机会。但高活动率也可能反映复杂度、服务质量或低容量利用，不能仅看一个数字就认定低效。", "ABC 局限：实施维护消耗资源；员工抵触陌生报告；想把一切分给产品的压力；把分配成本误作可避免成本；口径与对外报表不一致，需要两个系统和调节。", "AI 过程挖掘可帮助发现活动和时间，自动归类及更新成本率；人仍需选择活动颗粒度、验证因果关系、解释闲置产能并做经营决策。"], "summary": "ABM uses activity data to improve processes; benchmark comparable activities and avoid equating allocated costs with immediate savings.", "formula": "Reduce activity demand → Free resources → Redeploy or remove capacity → Realized savings", "trap": "活动次数下降，不保证固定资源支出立即下降。", "example": {"type": "choice", "prompt": {"en": "Reducing orders by 10% automatically cuts salaried order-processing cost by 10%.", "zh": "订单减少10%会自动让固定薪酬订单处理成本下降10%。"}, "options": [{"en": "False", "zh": "错误"}, {"en": "True", "zh": "正确"}], "answer": 0, "solution": {"en": "Capacity must be removed or redeployed for financial benefit.", "zh": "需要释放、取消或重新利用资源，才形成财务收益。"}}, "concept": {"type": "choice", "prompt": {"en": "A high ABC activity rate is best treated as:", "zh": "较高ABC活动率最好视为："}, "options": [{"en": "A clue requiring investigation", "zh": "需要调查的线索"}, {"en": "Proof of waste", "zh": "浪费的证明"}, {"en": "A guaranteed avoidable cost", "zh": "保证可避免的成本"}], "answer": 0, "solution": {"en": "Compare complexity, quality and utilization before conclusions.", "zh": "应比较复杂度、质量与利用率。"}}, "applications": [{"type": "choice", "prompt": {"en": "AI-selected cost drivers still require causal review.", "zh": "AI选择的驱动因素仍需因果审查。"}, "options": [{"en": "True", "zh": "正确"}, {"en": "False", "zh": "错误"}], "answer": 0, "solution": {"en": "Correlation alone is insufficient for defensible allocation.", "zh": "仅相关性不足以支持合理分配。"}}, {"type": "choice", "prompt": {"en": "Maintaining a very large ABC model can be costly.", "zh": "维护很大的ABC模型可能成本很高。"}, "options": [{"en": "True", "zh": "正确"}, {"en": "False", "zh": "错误"}], "answer": 0, "solution": {"en": "Data collection and maintenance are key implementation costs.", "zh": "数据采集维护是关键实施成本。"}}]}, {"id": "l5-tdabc", "section": 2, "title": {"en": "Time-driven ABC and practical capacity", "zh": "时间驱动ABC与实际可用产能"}, "pages": "73–78", "body": ["TDABC 以资源每单位时间成本和活动所需时间估计成本，减少大规模员工访谈及自报闲置比例的依赖。容量成本率 = 供给资源成本 / practical capacity。", "Practical capacity 是扣除休息、培训等后的可用时间，不能把实际使用时间当分母，否则闲置成本被塞进产品。课件常用理论产能75%–85%作为估计，实际应用需按情境测量。", "活动成本 = 时间率 × 所需分钟；已用资源成本 = 使用分钟 × 时间率；闲置成本 = 未用可用分钟 × 时间率。Baxter 的精确率634,500/1,404,000 ≈ 0.451923，显示0.45不等于中间计算应只用0.45。"], "summary": "TDABC applies a practical-capacity cost rate to required activity time and reports unused capacity separately.", "formula": "Capacity cost rate = Resource cost / Practical minutes; Cost = Rate × Minutes required", "trap": "先保留精确率，最后舍入；分母不是实际使用分钟。", "example": {"type": "number", "prompt": {"en": "Resource cost $60,000; practical capacity 120,000 minutes. Cost per minute?", "zh": "资源成本60,000，实际可用产能120,000分钟，求每分钟率。"}, "answer": 0.5, "solution": {"en": "60,000/120,000 = .50.", "zh": "60,000/120,000 = .50。"}, "unit": "$/min", "tolerance": 0.01}, "concept": {"type": "choice", "prompt": {"en": "Using actual utilized minutes instead of practical capacity would:", "zh": "用实际耗用分钟代替实际可用产能，可能："}, "options": [{"en": "Spread idle-capacity cost over used activity", "zh": "把闲置成本分摊给已用活动"}, {"en": "Always improve causality", "zh": "总能改善因果关系"}, {"en": "Make cost zero", "zh": "使成本为零"}], "answer": 0, "solution": {"en": "A smaller denominator loads idle resources onto used transactions.", "zh": "较小分母将闲置资源负担转给已发生交易。"}}, "applications": [{"type": "number", "prompt": {"en": "15 employees × 52 weeks × 2,400 minutes/week × 75%. Practical capacity in minutes?", "zh": "15名员工×52周×每周2,400分钟×75%，求实际可用产能分钟。"}, "answer": 1404000, "solution": {"en": "15 × 52 × 2,400 × .75 = 1,404,000.", "zh": "15 × 52 × 2,400 × .75 = 1,404,000。"}, "unit": "minutes", "tolerance": 0.01}, {"type": "number", "prompt": {"en": "Resource cost $634,500, capacity 1,404,000 minutes. Customer requires 59×30 + 15×90 + 15×80 minutes. Assigned cost, 2 decimals?", "zh": "成本634,500、产能1,404,000分钟；客户需59×30 + 15×90 + 15×80分钟，分配多少？"}, "answer": 1952.31, "solution": {"en": "Time = 4,320; rate = 634,500/1,404,000; cost = 1,952.3077 → 1,952.31.", "zh": "耗时4,320；乘精确率得到1,952.31。"}, "unit": "$", "tolerance": 0.02}]}], "exercises": [{"id": "l5-e1", "title": {"en": "Baxter: from pools to profitability", "zh": "Baxter：从成本池到产品及客户利润"}, "prompt": {"en": "Pools: orders $4.52m / 10,000 orders; designs $3.04m / 4,000 designs; machine activity $5.2m / 800,000 MH; customer relations $3.08m / 2,000 customers; Other $6.16m.\nSureStart: sales31.3m, DM9m, DL7m, shipping2m; 4,000 orders, zero designs,480,000MH.\nLongLife: sales18.7m, DM6m, DL5m, shipping1m;6,000 orders,4,000 designs,320,000MH.\nCustomer PE: sales29,200, DM7,500, DL6,700, shipping1,700;12 orders,4 designs,448MH,one customer.\nFind activity rates, each product’s overhead and margin, company income and PE’s margin. Compare with a traditional $14m MOH allocation based on total MH (exclude S&A from traditional product margins). Explain why the margins differ.", "zh": "成本池：订单4.52百万/10,000单；设计3.04百万/4,000次；机器5.2百万/800,000MH；客户关系3.08百万/2,000客户；Other6.16百万。\nSureStart收入31.3百万，DM9百万、DL7百万、运输2百万；4,000订单、0设计、480,000MH。\nLongLife收入18.7百万，DM6百万、DL5百万、运输1百万；6,000订单、4,000设计、320,000MH。\n客户PE收入29,200、DM7,500、DL6,700、运输1,700；12订单、4设计、448MH、1客户。\n求活动率、各产品分配额与利润、公司利润及PE利润。与按MH分配14百万MOH的传统产品利润比较（传统产品利润不扣S&A），解释差异。"}, "solution": {"en": "Rates: $452/order, $760/design, $6.50/MH, $1,540/customer.\nSureStart overhead=1.808m+3.12m=4.928m; margin=31.3−9−7−2−4.928=8.372m.\nLongLife overhead=2.712+3.04+2.08=7.832m; margin=18.7−6−5−1−7.832=−1.132m.\nCompany=8.372−1.132−3.08−6.16=−2m.\nPE overhead=5,424+3,040+2,912+1,540=12,916; margin=29,200−7,500−6,700−1,700−12,916=384.\nTraditional rate14m/800,000=$17.50/MH; overhead8.4m/5.6m; product margins6.9m/2.1m. Subtract all S&A11m from total9m → company−2m.\nThe traditional method ignores non-volume activity consumption, allocates all manufacturing overhead and excludes S&A from product margins. ABC changes the cost scope and attribution, revealing LongLife’s design and order intensity.", "zh": "率：订单452、设计760、机器6.50、客户1,540。\nSureStart分配1.808+3.12=4.928百万；利润31.3−9−7−2−4.928=8.372百万。\nLongLife分配2.712+3.04+2.08=7.832百万；利润18.7−6−5−1−7.832=−1.132百万。\n公司8.372−1.132−3.08−6.16=−2百万。\nPE分配5,424+3,040+2,912+1,540=12,916；利润384。\n传统率14百万/800,000=17.50/MH；分配8.4/5.6百万；产品利润6.9/2.1百万，合计9百万减全部S&A11百万=−2百万。\n传统方法忽略非产量活动差异、将全部制造费用分给产品，并在产品利润中排除S&A。ABC调整范围和归属，显示LongLife设计与订单资源需求高。"}, "cards": ["l5-first", "l5-rate", "l5-margin", "l5-overview"], "source": "Lecture 5 pp.20–64（课件整合题 / Lecture-based synthesis）"}, {"id": "l5-e2", "title": {"en": "TDABC: used and unused capacity", "zh": "TDABC：已用与闲置产能"}, "prompt": {"en": "15 employees earn $42,300 each annually. Each has 2,400 minutes per week,52 weeks,75% practical capacity. Activity time: order30min, design90min, assistance80min. All customers require10,000 orders,4,000 designs,2,000 assistance events.\nCompute practical capacity, exact cost rate, activity rates, utilized minutes, unused minutes and unused-capacity cost. Then compute Auto Services cost for59 orders,15 designs,15 assistance events. Do not round intermediate calculations.", "zh": "15名员工年薪各42,300；每人每周2,400分钟、52周、实际可用比例75%。活动耗时：订单30分钟、设计90分钟、协助80分钟。所有客户合计10,000订单、4,000设计、2,000协助。\n求实际可用产能、精确时间率、活动率、已用/闲置分钟及闲置成本。再算Auto Services的59订单、15设计、15协助成本。中间不舍入。"}, "solution": {"en": "Resource cost634,500; practical minutes15×2,400×52×.75=1,404,000. Rate=634,500/1,404,000=.4519230769 per minute.\nActivity rates13.5576923 /40.6730769 /36.1538462 dollars (display13.56/40.67/36.15).\nUsed minutes300,000+360,000+160,000=820,000. Unused584,000; used cost370,576.92; unused cost263,923.08; sum634,500.\nAuto Services minutes1,770+1,350+1,200=4,320; costs799.90+610.10+542.31=1,952.31 using unrounded values. The lecture’s order row $36.15 and total $1,188.56 do not follow from the stated activity counts.", "zh": "资源成本634,500；实际可用分钟15×2,400×52×.75=1,404,000；精确率.4519230769。\n活动率13.5576923/40.6730769/36.1538462，显示为13.56/40.67/36.15。\n已用分钟300,000+360,000+160,000=820,000；闲置584,000。已用成本370,576.92，闲置263,923.08，合计634,500。\nAuto Services耗时1,770+1,350+1,200=4,320；按精确率成本799.90+610.10+542.31=1,952.31。课件订单行36.15及总额1,188.56与所列活动数量不一致。"}, "cards": ["l5-tdabc", "l5-abm"], "source": "Lecture 5 pp.76–78（课件数据复算及补充 / Recomputed and extended）"}, {"id": "l5-e3", "title": {"en": "ABC vs traditional costing", "zh": "ABC 与传统成本法"}, "prompt": {"en": "ABC product cost automatically equals external inventory cost.\n1. False\n2. True", "zh": "ABC产品成本自动等于外部存货成本。\n1. 错误\n2. 正确"}, "solution": {"en": "False\nThe cost scope and exclusions can differ.", "zh": "错误\n成本范围和排除项目可能不同。"}, "cards": ["l5-overview"], "source": "原创基础题 / Original drill · 与模卡复测共享题目"}, {"id": "l5-e4", "title": {"en": "Activities, pools and five levels", "zh": "活动、成本池与五种层级"}, "prompt": {"en": "Maintaining a patent for one product is:\n1. Product-level\n2. Batch-level\n3. Unit-level", "zh": "维持某产品专利属于：\n1. 产品层级\n2. 批次层级\n3. 单位层级"}, "solution": {"en": "Product-level\nThe activity supports the product irrespective of units or batches.", "zh": "产品层级\n支持产品存在，不取决于件数或批数。"}, "cards": ["l5-levels"], "source": "原创基础题 / Original drill · 与模卡复测共享题目"}, {"id": "l5-e5", "title": {"en": "Five steps and first-stage allocation", "zh": "实施五步与第一阶段分配"}, "prompt": {"en": "Total indirect resources $22m; product pools $12.76m; customer pool $3.08m. Other pool in dollars?", "zh": "间接资源22百万，产品池12.76百万、客户池3.08百万，Other池多少美元？"}, "solution": {"en": "6160000 $\n22,000,000 − 12,760,000 − 3,080,000 = 6,160,000.", "zh": "6160000 $\n22,000,000 − 12,760,000 − 3,080,000 = 6,160,000。"}, "cards": ["l5-first"], "source": "原创基础题 / Original drill · 与模卡复测共享题目"}, {"id": "l5-e6", "title": {"en": "Activity rates and second-stage allocation", "zh": "活动率与第二阶段分配"}, "prompt": {"en": "Customer: 12 orders at $452, 4 designs at $760, 448 MH at $6.50, customer cost $1,540. Assigned overhead?", "zh": "客户12单×452、4设计×760、448MH×6.50、客户成本1,540，求分配额。"}, "solution": {"en": "12916 $\n5,424 + 3,040 + 2,912 + 1,540 = 12,916.", "zh": "12916 $\n5,424 + 3,040 + 2,912 + 1,540 = 12,916。"}, "cards": ["l5-rate"], "source": "原创基础题 / Original drill · 与模卡复测共享题目"}, {"id": "l5-e7", "title": {"en": "Product and customer profitability", "zh": "产品与客户盈利分析"}, "prompt": {"en": "LongLife revenue $18.7m, DM $6m, DL $5m, shipping $1m, ABC overhead $7.832m. Product margin in dollars?", "zh": "LongLife收入18.7百万，DM6百万、DL5百万、运输1百万、ABC7.832百万，求产品利润美元。"}, "solution": {"en": "-1132000 $\n18,700,000 − 6,000,000 − 5,000,000 − 1,000,000 − 7,832,000 = −1,132,000.", "zh": "-1132000 $\n18,700,000 − 19,832,000 = −1,132,000。"}, "cards": ["l5-margin"], "source": "原创基础题 / Original drill · 与模卡复测共享题目"}, {"id": "l5-e8", "title": {"en": "ABM, benchmarking and limitations", "zh": "作业管理、标杆与局限"}, "prompt": {"en": "Maintaining a very large ABC model can be costly.\n1. True\n2. False", "zh": "维护很大的ABC模型可能成本很高。\n1. 正确\n2. 错误"}, "solution": {"en": "True\nData collection and maintenance are key implementation costs.", "zh": "正确\n数据采集维护是关键实施成本。"}, "cards": ["l5-abm"], "source": "原创基础题 / Original drill · 与模卡复测共享题目"}, {"id": "l5-e9", "title": {"en": "Time-driven ABC and practical capacity", "zh": "时间驱动ABC与实际可用产能"}, "prompt": {"en": "Resource cost $634,500, capacity 1,404,000 minutes. Customer requires 59×30 + 15×90 + 15×80 minutes. Assigned cost, 2 decimals?", "zh": "成本634,500、产能1,404,000分钟；客户需59×30 + 15×90 + 15×80分钟，分配多少？"}, "solution": {"en": "1952.31 $\nTime = 4,320; rate = 634,500/1,404,000; cost = 1,952.3077 → 1,952.31.", "zh": "1952.31 $\n耗时4,320；乘精确率得到1,952.31。"}, "cards": ["l5-tdabc"], "source": "原创基础题 / Original drill · 与模卡复测共享题目"}], "notes": [{"title": "TDABC Auto Services 行的数字不一致", "body": "PDF p.78：59订单×30分钟×(634,500/1,404,000)=799.90，而不是表中36.15；加15设计与15协助后合计1,952.31，而非1,188.56。计算使用精确时间率，显示金额最后保留两位。"}]}], "sources": [{"name": "ACT6121 Lecture 1.pdf", "pages": 78, "scope": "Lecture 1-1 / 1-2 / 人工成本补充"}, {"name": "ACT6121 Lecture 2.pdf", "pages": 147, "scope": "Job-order / Process / WA / FIFO / Operation costing"}, {"name": "ACT6121 Lecture 3 CVP.pdf", "pages": 106, "scope": "Contribution / CVP / Leverage / Sales mix"}, {"name": "ACT6121 Lecture 4 Variable Costing.pdf", "pages": 81, "scope": "Segments / VC / AC / Reconciliation"}, {"name": "ACT6121 Lecture 5 ABC.pdf", "pages": 80, "scope": "ABC / ABM / TDABC"}, {"name": "Tutorial 1 + solutions", "pages": 12, "scope": "Q1–Q4；含图像表格已逐页核对"}, {"name": "Tutorial 2", "pages": 3, "scope": "Q1–Q3；未提供官方答案，解析独立复算"}, {"name": "Tut1+Sheet.xlsx", "scope": "Q1–Q4、Sheet1方法对比；只读核对，未修改原表"}], "scopeNote": "覆盖当前已上传 Lecture 1–5 的知识点；case study 文件夹未读取。Lecture 1课程大纲提到 life-cycle costs，但尚无该章课件，因此未假定已经讲完或排除出最终考试。后续上传后可新增章节。页码均指PDF文件页序，不是幻灯片页脚编号。", "methodNote": "每张模卡有1道讲解例题、1道概念题和2道应用/辨析题。一次测验抽概念题及一题应用，两题全对记为本轮掌握；答错进入回炉，复测轮换应用题。有限题库只能证明本轮表现，不代表长期掌握。基础章节练习与应用题共享，综合tutorial独立列示。", "research": [{"title": "Retrieval practice — The Learning Scientists", "url": "https://www.learningscientists.org/faq"}, {"title": "Spaced repetition — Anki Manual", "url": "https://docs.ankiweb.net/background.html"}]};
